alter table public.student_guardians drop constraint if exists student_guardians_linked_via_check;
alter table public.student_guardians add constraint student_guardians_linked_via_check
  check (linked_via in ('passport', 'claim_code', 'invite', 'class_code', 'admin', 'import', 'event_card', 'league', 'training'));

-------------------------------------------------------------------------------
-- 1. Nội dung giáo án (admin quản lý)
-------------------------------------------------------------------------------
create table public.training_programs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  code text not null unique,
  name_vi text not null,
  name_en text not null default '',
  kind text not null check (kind in ('break', 'home', 'fitness', 'ladder')),
  audience text not null default 'adult' check (audience in ('adult', 'junior', 'all')),
  target_hcp_min numeric(4,1),
  target_hcp_max numeric(4,1),
  weeks int not null check (weeks between 1 and 52),
  days_per_week int not null default 3 check (days_per_week between 1 and 7),
  summary_vi text,
  summary_en text,
  is_active boolean not null default true,
  version int not null default 1,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.training_program_sessions (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  program_id uuid not null references public.training_programs(id) on delete cascade,
  week_no int not null check (week_no >= 1),
  -- 0 = dùng chung cho mọi ngày tập của tuần; 1..days_per_week = buổi riêng của ngày đó
  day_no int not null default 0 check (day_no >= 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (program_id, week_no, day_no)
);

create table public.training_program_blocks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  session_id uuid not null references public.training_program_sessions(id) on delete cascade,
  sort_order int not null,
  area text not null check (area in ('fir', 'gir', 'scr', 'chip', 'putt')),
  title_vi text not null,
  title_en text not null default '',
  est_minutes int not null check (est_minutes > 0),
  -- [{ "t": p|o|h|b|s|d, "vi": "...", "en": "" }]: p đoạn văn, o mục tiêu, h tiêu đề bài, b/s/d dòng bài tập
  lines jsonb not null default '[]' check (jsonb_typeof(lines) = 'array'),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (session_id, sort_order)
);
create index training_program_blocks_session_idx on public.training_program_blocks (session_id, sort_order);

-- Chuẩn thống kê theo handicap. mode 'step': giá trị của mốc đầu tiên có hcp ≥ handicap; 'linear': nội suy giữa các mốc.
create table public.training_stat_benchmarks (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  stat text not null check (stat in ('fir_pct', 'gir_pct', 'scramble_pct', 'putts_per_18', 'three_putt_pct')),
  mode text not null check (mode in ('step', 'linear')),
  hcp numeric(4,1) not null,
  value numeric(5,1) not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (stat, hcp)
);

-------------------------------------------------------------------------------
-- 2. Dữ liệu người tập
-------------------------------------------------------------------------------
create table public.training_goals (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  hcp_start numeric(4,1),
  hcp_start_source text not null check (hcp_start_source in ('self_declared', 'intake_test', 'whs', 'none')),
  hcp_target numeric(4,1) not null check (hcp_target between -10 and 54),
  months int not null check (months between 1 and 24),
  start_date date not null default public.vn_today(),
  program_id uuid not null references public.training_programs(id),
  program_version int not null,
  schedule_mode text not null check (schedule_mode in ('fixed_12_weeks', 'flexible')),
  days_of_week int[] not null check (cardinality(days_of_week) between 1 and 7 and days_of_week <@ array[0,1,2,3,4,5,6]),
  session_minutes int not null default 60 check (session_minutes between 5 and 600),
  weak_area text check (weak_area in ('fir', 'gir', 'scr', 'chip', 'putt')),
  reminders_on boolean not null default true,
  cursor_week int not null default 1,
  cursor_day int not null default 1,
  cursor_block int not null default 0,
  cursor_fraction numeric(6,5) not null default 0 check (cursor_fraction >= 0 and cursor_fraction < 1),
  status text not null default 'active' check (status in ('active', 'completed', 'replaced', 'cancelled')),
  completed_at timestamptz,
  ended_at timestamptz,
  merge_trail uuid[] not null default '{}',
  created_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create unique index training_goals_one_active on public.training_goals (student_id) where status = 'active';
create index training_goals_student_idx on public.training_goals (student_id, created_at desc);

create table public.training_intake_tests (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  goal_id uuid references public.training_goals(id),
  putt_made int not null check (putt_made between 0 and 5),
  chip_close int not null check (chip_close between 0 and 5),
  tee_fairway int not null check (tee_fairway between 0 and 5),
  est_hcp_putt numeric(4,1),
  est_hcp_chip numeric(4,1),
  est_hcp_long numeric(4,1),
  weak_area text check (weak_area in ('fir', 'gir', 'scr', 'chip', 'putt')),
  taken_at timestamptz not null default now(),
  merge_trail uuid[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index training_intake_tests_student_idx on public.training_intake_tests (student_id, taken_at desc);

create table public.training_session_logs (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  goal_id uuid not null references public.training_goals(id),
  practiced_on date not null,
  planned_minutes int not null default 0,
  done_minutes numeric(6,1) not null default 0,
  note text,
  merge_trail uuid[] not null default '{}',
  created_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index training_session_logs_student_idx on public.training_session_logs (student_id, practiced_on desc);
create index training_session_logs_goal_idx on public.training_session_logs (goal_id, practiced_on);

create table public.training_session_items (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  log_id uuid not null references public.training_session_logs(id) on delete cascade,
  block_id uuid not null references public.training_program_blocks(id),
  sort_order int not null,
  unit_from int not null check (unit_from >= 0),
  unit_to int not null,
  unit_total int not null check (unit_total > 0),
  completed boolean not null default false,
  result_text text,
  result_made int,
  result_attempts int,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (unit_to > unit_from and unit_to <= unit_total)
);
create index training_session_items_log_idx on public.training_session_items (log_id, sort_order);

create table public.round_stats (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  played_on date not null,
  course_name text,
  holes_played int not null check (holes_played in (9, 18)),
  tee_name text,
  total_strokes int,
  source text not null default 'training' check (source in ('training')),
  note text,
  merge_trail uuid[] not null default '{}',
  created_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);
create index round_stats_student_idx on public.round_stats (student_id, played_on desc);

create table public.round_stat_holes (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  round_id uuid not null references public.round_stats(id) on delete cascade,
  hole_no int not null check (hole_no between 1 and 18),
  par int not null check (par between 3 and 6),
  strokes int check (strokes between 1 and 20),
  fairway text check (fairway in ('hit', 'left', 'right', 'na')),
  gir boolean,
  putts int check (putts between 0 and 10),
  penalties int check (penalties between 0 and 10),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (round_id, hole_no)
);

-- Mỗi lần đo là một dòng (giữ lịch sử); số đang dùng = lần đo mới nhất của gậy đó
create table public.club_distances (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null default public.default_org_id() references public.organizations(id),
  student_id uuid not null references public.students(id),
  club_code text not null check (club_code in ('dr', '3w', '5w', '7w', 'h3', 'h4', 'h5', '3i', '4i', '5i', '6i', '7i', '8i', '9i', 'pw', 'gw', 'sw', 'lw')),
  carry_yards int check (carry_yards between 1 and 400),
  total_yards int check (total_yards between 1 and 450),
  measured_on date not null default public.vn_today(),
  merge_trail uuid[] not null default '{}',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  check (carry_yards is not null or total_yards is not null)
);
create index club_distances_student_idx on public.club_distances (student_id, club_code, measured_on desc);

do $$
declare t text;
begin
  foreach t in array array['training_programs', 'training_program_sessions', 'training_program_blocks', 'training_stat_benchmarks',
    'training_goals', 'training_intake_tests', 'training_session_logs', 'training_session_items', 'round_stats', 'round_stat_holes', 'club_distances'] loop
    execute format('create trigger set_updated_at before update on public.%I for each row execute function public.set_updated_at()', t);
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on public.%I from anon', t);
  end loop;
end $$;

-------------------------------------------------------------------------------
-- 3. Hàm quyền
-------------------------------------------------------------------------------
-- Được dùng mục Tập luyện: admin; hoặc visibility = all; hoặc beta và có trong danh sách thử
create or replace function public.training_enabled()
returns boolean language sql stable security definer set search_path = public as $$
  select auth.uid() is not null and (
    public.is_admin()
    or coalesce((select value #>> '{}' from public.app_settings where key = 'training.visibility'), 'off') = 'all'
    or (coalesce((select value #>> '{}' from public.app_settings where key = 'training.visibility'), 'off') = 'beta'
        and coalesce((select value from public.app_settings where key = 'training.beta_user_ids'), '[]'::jsonb) ? auth.uid()::text))
$$;

-- Hồ sơ golfer của chính người đang đăng nhập (quan hệ self, đang hoạt động)
create or replace function public.training_self_student()
returns uuid language sql stable security definer set search_path = public as $$
  select sg.student_id from public.student_guardians sg
  join public.guardians g on g.id = sg.guardian_id
  join public.students s on s.id = sg.student_id
  where g.user_id = auth.uid() and g.deleted_at is null and sg.deleted_at is null
    and sg.relationship = 'self' and sg.status = 'active' and sg.can_manage
    and s.deleted_at is null and s.merged_into_student_id is null
  order by sg.linked_at nulls last, sg.created_at
  limit 1
$$;

-- Chính người tập (hồ sơ self) hoặc admin
create or replace function public.training_can_manage(p_student_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_admin() or (public.training_enabled() and public.can_manage_student(p_student_id))
$$;

-------------------------------------------------------------------------------
-- 4. RLS
-------------------------------------------------------------------------------
create policy training_content_read on public.training_programs for select to authenticated using (public.training_enabled());
create policy training_content_admin on public.training_programs for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy training_content_read on public.training_program_sessions for select to authenticated using (public.training_enabled());
create policy training_content_admin on public.training_program_sessions for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy training_content_read on public.training_program_blocks for select to authenticated using (public.training_enabled());
create policy training_content_admin on public.training_program_blocks for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy training_content_read on public.training_stat_benchmarks for select to authenticated using (public.training_enabled());
create policy training_content_admin on public.training_stat_benchmarks for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Mục tiêu và buổi tập: đọc trực tiếp; ghi qua hàm (training_start_goal, training_save_session). Chỉ cho sửa vài cột cài đặt lịch.
create policy training_goals_read on public.training_goals for select to authenticated using (public.training_can_manage(student_id));
create policy training_goals_update on public.training_goals for update to authenticated
  using (public.training_can_manage(student_id) and status = 'active') with check (public.training_can_manage(student_id));
revoke update on public.training_goals from authenticated;
grant update (schedule_mode, days_of_week, session_minutes, reminders_on, weak_area) on public.training_goals to authenticated;

create policy training_logs_read on public.training_session_logs for select to authenticated using (public.training_can_manage(student_id));
create policy training_items_read on public.training_session_items for select to authenticated
  using (exists (select 1 from public.training_session_logs l where l.id = log_id and public.training_can_manage(l.student_id)));

create policy training_intake_read on public.training_intake_tests for select to authenticated using (public.training_can_manage(student_id));
create policy training_intake_insert on public.training_intake_tests for insert to authenticated with check (public.training_can_manage(student_id));

create policy round_stats_rw on public.round_stats for all to authenticated
  using (public.training_can_manage(student_id)) with check (public.training_can_manage(student_id));
create policy round_stat_holes_rw on public.round_stat_holes for all to authenticated
  using (exists (select 1 from public.round_stats r where r.id = round_id and public.training_can_manage(r.student_id)))
  with check (exists (select 1 from public.round_stats r where r.id = round_id and public.training_can_manage(r.student_id)));

create policy club_distances_rw on public.club_distances for all to authenticated
  using (public.training_can_manage(student_id)) with check (public.training_can_manage(student_id));

-------------------------------------------------------------------------------
-- 5. Tạo hồ sơ golfer của tôi (cách B). Luôn tạo hồ sơ mới chờ xác minh; không tự nối vào hồ sơ có sẵn
--    (tránh nhận nhầm hồ sơ người khác). Hồ sơ trùng tên + ngày sinh hiện ở hàng chờ duyệt để admin gộp.
-------------------------------------------------------------------------------
create or replace function public.training_create_self_profile(p_full_name text, p_date_of_birth date, p_gender text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_name text := btrim(coalesce(p_full_name, ''));
  v_existing uuid := public.training_self_student();
  v_min int := public.setting_int('training.min_age', 18);
  v_guardian uuid;
  v_student uuid;
  v_matches int;
begin
  if not public.training_enabled() then raise exception 'training_disabled' using errcode = '42501'; end if;
  if v_existing is not null then
    return jsonb_build_object('student_id', v_existing, 'created', false,
      'student_code', (select student_code from public.students where id = v_existing));
  end if;
  if v_name = '' then raise exception 'name_required' using errcode = '22023'; end if;
  if p_date_of_birth is null or p_date_of_birth > public.vn_today() then raise exception 'dob_required' using errcode = '22023'; end if;
  if date_part('year', age(public.vn_today(), p_date_of_birth)) < v_min then raise exception 'under_min_age' using errcode = '22023'; end if;
  if p_gender is not null and p_gender not in ('male', 'female', 'other') then raise exception 'gender_invalid' using errcode = '22023'; end if;

  select count(*) into v_matches from public.students s
  where s.deleted_at is null and s.merged_into_student_id is null
    and s.full_name_normalized = public.normalize_name(v_name) and s.date_of_birth = p_date_of_birth;

  v_guardian := public.ensure_my_guardian();
  insert into public.students (full_name, date_of_birth, birth_year, gender, verification_status, self_reported)
  values (v_name, p_date_of_birth, extract(year from p_date_of_birth)::int, p_gender, 'pending_review',
          jsonb_build_object('source', 'training', 'submitted_at', now(), 'full_name', v_name,
                             'date_of_birth', p_date_of_birth, 'match_count', v_matches))
  returning id into v_student;
  insert into public.student_guardians (student_id, guardian_id, relationship, is_primary, can_manage, linked_via, status, linked_at)
  values (v_student, v_guardian, 'self', true, true, 'training', 'active', now());
  insert into public.audit_logs (actor_user_id, action, entity_type, entity_id, after)
  values (auth.uid(), 'training.create_self_profile', 'student', v_student, jsonb_build_object('match_count', v_matches));
  return jsonb_build_object('student_id', v_student, 'created', true, 'match_count', v_matches,
    'student_code', (select student_code from public.students where id = v_student));
end $$;

-------------------------------------------------------------------------------
-- 6. Mục tiêu và con trỏ giáo án
-------------------------------------------------------------------------------
-- Buổi giáo án của (chương trình, tuần, ngày): ưu tiên buổi riêng của ngày, không có thì buổi chung (day_no = 0)
create or replace function public.training_session_for(p_program uuid, p_week int, p_day int)
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.training_program_sessions
  where program_id = p_program and week_no = p_week and day_no in (0, p_day)
  order by day_no desc limit 1
$$;

create or replace function public.training_start_goal(p_data jsonb)
returns uuid language plpgsql volatile security definer set search_path = public as $$
declare
  v_student uuid := coalesce(nullif(p_data ->> 'student_id', '')::uuid, public.training_self_student());
  v_prog record;
  v_target numeric := (p_data ->> 'hcp_target')::numeric;
  v_dob date;
  v_id uuid;
  v_days int[];
begin
  if v_student is null then raise exception 'no_profile' using errcode = '22023'; end if;
  if not public.training_can_manage(v_student) then raise exception 'forbidden' using errcode = '42501'; end if;
  select date_of_birth into v_dob from public.students where id = v_student;
  if v_dob is null then raise exception 'dob_required' using errcode = '22023'; end if;
  if date_part('year', age(public.vn_today(), v_dob)) < public.setting_int('training.min_age', 18) then
    raise exception 'under_min_age' using errcode = '22023';
  end if;
  if v_target is null then raise exception 'target_required' using errcode = '22023'; end if;
  select array_agg(distinct x::int order by x::int) into v_days from jsonb_array_elements_text(coalesce(p_data -> 'days_of_week', '[]')) x;

  if nullif(p_data ->> 'program_code', '') is not null then
    select * into v_prog from public.training_programs where code = p_data ->> 'program_code' and is_active;
  else
    -- Tự chọn theo handicap mục tiêu
    select * into v_prog from public.training_programs
    where kind = 'break' and is_active and audience in ('adult', 'all')
      and (target_hcp_min is null or v_target >= target_hcp_min) and (target_hcp_max is null or v_target <= target_hcp_max)
    order by sort_order limit 1;
  end if;
  if v_prog.id is null then raise exception 'program_not_found' using errcode = '22023'; end if;

  update public.training_goals set status = 'replaced', ended_at = now() where student_id = v_student and status = 'active';
  insert into public.training_goals (student_id, hcp_start, hcp_start_source, hcp_target, months, program_id, program_version,
                                     schedule_mode, days_of_week, session_minutes, weak_area, created_by)
  values (v_student, nullif(p_data ->> 'hcp_start', '')::numeric, coalesce(nullif(p_data ->> 'hcp_start_source', ''), 'self_declared'),
          v_target, coalesce((p_data ->> 'months')::int, 6), v_prog.id, v_prog.version,
          coalesce(nullif(p_data ->> 'schedule_mode', ''), 'flexible'), coalesce(v_days, '{2,4,6}'),
          coalesce((p_data ->> 'session_minutes')::int, 60), nullif(p_data ->> 'weak_area', ''), auth.uid())
  returning id into v_id;
  update public.training_intake_tests set goal_id = v_id
  where student_id = v_student and goal_id is null and taken_at > now() - interval '1 day';
  return v_id;
end $$;

-- Lưu một buổi tập. p_items: [{ block_id, unit_from, unit_to, unit_total, completed, result_text }] theo thứ tự đã làm.
-- Các phần đã xong phải nối tiếp từ con trỏ hiện tại; phần đầu tiên chưa xong dừng việc dời con trỏ.
create or replace function public.training_save_session(p_goal_id uuid, p_practiced_on date, p_planned_minutes int,
                                                       p_items jsonb, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  g public.training_goals%rowtype;
  p public.training_programs%rowtype;
  v_log uuid;
  v_item jsonb;
  v_i int := 0;
  v_moving boolean := true;
  v_session uuid;
  v_block public.training_program_blocks%rowtype;
  v_from int; v_to int; v_total int;
  v_done numeric := 0;
  v_ok int := 0;
  v_n_blocks int;
  v_m text[];
begin
  select * into g from public.training_goals where id = p_goal_id for update;
  if g.id is null or g.status <> 'active' then raise exception 'goal_not_active' using errcode = '22023'; end if;
  if not public.training_can_manage(g.student_id) then raise exception 'forbidden' using errcode = '42501'; end if;
  if jsonb_typeof(coalesce(p_items, 'null')) <> 'array' or jsonb_array_length(p_items) = 0 then
    raise exception 'items_required' using errcode = '22023';
  end if;
  if p_practiced_on is null or p_practiced_on > public.vn_today() then raise exception 'date_invalid' using errcode = '22023'; end if;
  select * into p from public.training_programs where id = g.program_id;

  insert into public.training_session_logs (student_id, goal_id, practiced_on, planned_minutes, note, created_by)
  values (g.student_id, g.id, p_practiced_on, coalesce(p_planned_minutes, 0), nullif(btrim(coalesce(p_note, '')), ''), auth.uid())
  returning id into v_log;

  for v_item in select * from jsonb_array_elements(p_items) loop
    select * into v_block from public.training_program_blocks where id = (v_item ->> 'block_id')::uuid;
    if v_block.id is null then raise exception 'block_not_found' using errcode = '22023'; end if;
    v_from := (v_item ->> 'unit_from')::int; v_to := (v_item ->> 'unit_to')::int; v_total := (v_item ->> 'unit_total')::int;
    v_m := regexp_match(coalesce(v_item ->> 'result_text', ''), '(\d+)\s*/\s*(\d+)');
    insert into public.training_session_items (log_id, block_id, sort_order, unit_from, unit_to, unit_total, completed,
                                               result_text, result_made, result_attempts)
    values (v_log, v_block.id, v_i, v_from, v_to, v_total, coalesce((v_item ->> 'completed')::boolean, false),
            nullif(btrim(coalesce(v_item ->> 'result_text', '')), ''),
            case when v_m is not null then v_m[1]::int end, case when v_m is not null then v_m[2]::int end);
    v_i := v_i + 1;

    if v_moving and coalesce((v_item ->> 'completed')::boolean, false) then
      -- Phần này phải đúng vị trí con trỏ
      v_session := public.training_session_for(g.program_id, g.cursor_week, g.cursor_day);
      if v_block.session_id <> v_session or v_block.sort_order <> g.cursor_block then
        raise exception 'out_of_order' using errcode = '22023';
      end if;
      if abs(v_from::numeric / v_total - g.cursor_fraction) > 0.0001 then raise exception 'out_of_order' using errcode = '22023'; end if;
      v_done := v_done + v_block.est_minutes * (v_to - v_from)::numeric / v_total;
      v_ok := v_ok + 1;
      if v_to >= v_total then
        g.cursor_block := g.cursor_block + 1; g.cursor_fraction := 0;
        select count(*) into v_n_blocks from public.training_program_blocks where session_id = v_session;
        if g.cursor_block >= v_n_blocks then
          g.cursor_block := 0; g.cursor_day := g.cursor_day + 1;
          if g.cursor_day > p.days_per_week then g.cursor_day := 1; g.cursor_week := g.cursor_week + 1; end if;
        end if;
      else
        g.cursor_fraction := v_to::numeric / v_total;
      end if;
    else
      v_moving := false;
    end if;
  end loop;

  update public.training_session_logs set done_minutes = round(v_done, 1) where id = v_log;
  update public.training_goals
  set cursor_week = g.cursor_week, cursor_day = g.cursor_day, cursor_block = g.cursor_block, cursor_fraction = g.cursor_fraction,
      status = case when g.cursor_week > p.weeks then 'completed' else status end,
      completed_at = case when g.cursor_week > p.weeks then now() else completed_at end
  where id = g.id;
  return jsonb_build_object('log_id', v_log, 'completed_items', v_ok, 'done_minutes', round(v_done, 1),
    'cursor', jsonb_build_object('week', g.cursor_week, 'day', g.cursor_day, 'block', g.cursor_block, 'fraction', g.cursor_fraction),
    'program_completed', g.cursor_week > p.weeks);
end $$;

-- Chuẩn thống kê cho một handicap
create or replace function public.training_benchmark(p_stat text, p_hcp numeric)
returns numeric language plpgsql stable security definer set search_path = public as $$
declare v_mode text; lo record; hi record;
begin
  select mode into v_mode from public.training_stat_benchmarks where stat = p_stat limit 1;
  if v_mode is null then return null; end if;
  if v_mode = 'step' then
    return coalesce((select value from public.training_stat_benchmarks where stat = p_stat and hcp >= p_hcp order by hcp limit 1),
                    (select value from public.training_stat_benchmarks where stat = p_stat order by hcp desc limit 1));
  end if;
  select hcp, value into lo from public.training_stat_benchmarks where stat = p_stat and hcp <= p_hcp order by hcp desc limit 1;
  select hcp, value into hi from public.training_stat_benchmarks where stat = p_stat and hcp >= p_hcp order by hcp limit 1;
  if lo.hcp is null then return hi.value; end if;
  if hi.hcp is null or hi.hcp = lo.hcp then return lo.value; end if;
  return round(lo.value + (hi.value - lo.value) * (p_hcp - lo.hcp) / (hi.hcp - lo.hcp), 1);
end $$;

-------------------------------------------------------------------------------
-- 7. Nhắc tập (chỉ trong app ở đợt 1). pg_cron 23:00 UTC = 6:00 giờ Việt Nam.
-------------------------------------------------------------------------------
create or replace function public.training_send_reminders()
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  v_today date := public.vn_today();
  g record;
  v_last date;
  v_missed int;
  v_type text;
  v_n int := 0;
  u uuid;
begin
  if coalesce((select value #>> '{}' from public.app_settings where key = 'training.visibility'), 'off') = 'off' then return 0; end if;
  for g in select tg.* from public.training_goals tg join public.students s on s.id = tg.student_id
           where tg.status = 'active' and tg.reminders_on and s.deleted_at is null loop
    if not (extract(dow from v_today)::int = any(g.days_of_week)) then continue; end if;
    select max(practiced_on) into v_last from public.training_session_logs where goal_id = g.id;
    -- Số ngày có lịch đã qua kể từ lần tập cuối (hoặc từ ngày bắt đầu), không tính hôm nay
    select count(*) into v_missed from generate_series(greatest(coalesce(v_last + 1, g.start_date), v_today - 30), v_today - 1, interval '1 day') d
    where extract(dow from d)::int = any(g.days_of_week);
    v_type := case when v_missed >= 7 then 'training_missed_7d' when v_missed >= 3 then 'training_missed_3d' else 'training_today' end;
    for u in select public.staff_self_users(g.student_id) loop
      continue when u is null;
      -- Một thông báo tập luyện mỗi người mỗi ngày
      continue when exists (select 1 from public.notifications n where n.user_id = u and n.type like 'training_%'
                            and (n.created_at at time zone 'Asia/Ho_Chi_Minh')::date = v_today);
      -- Nhắc bỏ lỡ chỉ gửi một lần cho mỗi đợt bỏ lỡ
      continue when v_type <> 'training_today' and exists (select 1 from public.notifications n where n.user_id = u and n.type = v_type
                            and n.created_at > coalesce(v_last, g.start_date)::timestamp at time zone 'Asia/Ho_Chi_Minh');
      insert into public.notifications (user_id, type, title_vi, title_en, body_vi, body_en, link)
      values (u, v_type,
        case v_type when 'training_today' then 'Hôm nay có buổi tập' when 'training_missed_3d' then 'Đã 3 buổi chưa tập' else 'Một tuần chưa tập rồi' end,
        case v_type when 'training_today' then 'Training day today' when 'training_missed_3d' then '3 sessions missed' else 'A week without training' end,
        case v_type when 'training_today' then 'Mở mục Tập luyện để xem buổi tập hôm nay.'
                    when 'training_missed_3d' then 'Tập lại hôm nay để giữ nhịp. Buổi ngắn 10–15 phút cũng tính.'
                    else 'Mục tiêu vẫn đang chờ. Có thể bớt thời lượng mỗi buổi hoặc đổi ngày tập trong Kế hoạch tuần.' end,
        case v_type when 'training_today' then 'Open Training to see today''s session.'
                    when 'training_missed_3d' then 'Train today to keep your rhythm. A short 10–15 minute session counts.'
                    else 'Your goal is waiting. You can shorten sessions or change training days in the weekly plan.' end,
        '/app/training');
      v_n := v_n + 1;
    end loop;
  end loop;
  return v_n;
end $$;
select cron.schedule('training-reminders', '0 23 * * *', 'select public.training_send_reminders()');

-------------------------------------------------------------------------------
-- 8. Gộp hồ sơ: dữ liệu tập luyện đi theo hồ sơ giữ lại; bỏ gộp thì trả về (giống grade_history_follow_student_merge)
-------------------------------------------------------------------------------
create or replace function public.training_follow_student_merge()
returns trigger language plpgsql security definer set search_path = public as $$
declare t text; k uuid := new.merged_into_student_id;
begin
  if old.merged_into_student_id is null and new.merged_into_student_id is not null then
    -- Hồ sơ giữ lại đã có mục tiêu đang chạy: mục tiêu của hồ sơ bị gộp chuyển sang 'replaced'
    if exists (select 1 from public.training_goals where student_id = k and status = 'active') then
      update public.training_goals set status = 'replaced', ended_at = now() where student_id = old.id and status = 'active';
    end if;
    foreach t in array array['training_goals', 'training_intake_tests', 'training_session_logs', 'round_stats', 'club_distances'] loop
      execute format('update public.%I set student_id = $1, merge_trail = merge_trail || $2 where student_id = $2', t) using k, old.id;
    end loop;
  elsif old.merged_into_student_id is not null and new.merged_into_student_id is null then
    foreach t in array array['training_goals', 'training_intake_tests', 'training_session_logs', 'round_stats', 'club_distances'] loop
      execute format('update public.%I set student_id = $1, merge_trail = merge_trail[1:cardinality(merge_trail) - 1]
                      where merge_trail[cardinality(merge_trail)] = $1', t) using old.id;
    end loop;
  end if;
  return null;
end $$;
create trigger training_follow_student_merge after update of merged_into_student_id on public.students
  for each row execute function public.training_follow_student_merge();

-------------------------------------------------------------------------------
-- 9. Quyền gọi hàm
-------------------------------------------------------------------------------
do $$
declare f text;
begin
  revoke execute on function public.training_follow_student_merge() from public, anon, authenticated;
  revoke execute on function public.training_send_reminders() from public, anon, authenticated;
  revoke execute on function public.training_session_for(uuid, int, int) from public, anon;
  foreach f in array array[
    'public.training_enabled()', 'public.training_self_student()', 'public.training_can_manage(uuid)',
    'public.training_create_self_profile(text, date, text)', 'public.training_start_goal(jsonb)',
    'public.training_save_session(uuid, date, int, jsonb, text)', 'public.training_benchmark(text, numeric)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end $$;

