  d jsonb := $json${"b90":[{"w":1,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing nửa vòng với gậy sắt 7 (không bóng), tập trung đường swing từ trong ra ngoài."],["b","10 cú swing nửa vòng với gậy sắt 7, tập trung tiếp xúc bóng chắc."],["b","25 lần swing 3/4 với gậy sắt 7 (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing 3/4 với gậy sắt 7, tập trung tiếp xúc ổn định"],["b","25 lần swing toàn phần với gậy sắt 7 (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing toàn phần với gậy sắt 7, tập trung tiếp xúc chắc"],["p","Hướng dẫn: Nếu chưa rõ đường swing từ trong ra ngoài là gì, xem lại phần kiến thức. Đây là cách chữa phổ biến cho người hay slice, và cũng giúp cả người hay hook. Với 3 bộ 10 cú đánh có bóng, nên đặt bóng trên tee để tiếp xúc tốt hơn. Tập trung tiếp xúc chắc với cú swing có kiểm soát, loại bỏ càng nhiều cú đánh xuống đất (chunk) càng tốt."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR: Hình dung một green quanh mục tiêu khoảng cách trên sân tập"],["b","10 lần swing nửa vòng không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với wedge, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách với wedge."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down từ fringe bằng wedge chip quen dùng"],["s","Hoàn thành 10 up & down tới lỗ gần (cách 10–15 ft)"],["s","Hoàn thành 5 up & down tới lỗ trung bình (cách 25–30 ft)"],["s","Hoàn thành 5 up & down tới lỗ xa (cách 35–40 ft trở lên)"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Putt trượt thì lượt đó không tính. Hoàn thành 10 lượt ở lỗ gần rồi chuyển sang 5 lượt ở lỗ trung bình và 5 lượt ở lỗ xa."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe"],["o","Cải thiện kiểm soát khoảng cách tới lỗ gần, trung bình và xa"],["o","Cải thiện khả năng chip bóng dừng trong 3 feet quanh lỗ"],["p","Bài tập hôm nay:"],["h","1. Chip từ fringe"],["s","50 cú chip tới lỗ xa (40 ft trở lên). Ghi số bóng dừng trong 3 feet quanh lỗ."],["s","50 cú chip tới lỗ trung bình (cách 25 ft). Ghi số bóng dừng trong 3 feet quanh lỗ."],["s","50 cú chip tới lỗ gần (10–15 ft). Ghi số bóng dừng trong 3 feet quanh lỗ."],["s","50 cú chip luân phiên ngẫu nhiên tới cả 3 lỗ."],["p","Tổng số cú chip hôm nay: 200"],["p","Hướng dẫn: Đánh 5 bộ 10 bóng hoặc 10 bộ 5 bóng để đủ 50 lượt cho mỗi bài trong 4 bài. Dùng mác bóng hoặc tee tạo vòng tròn bán kính 3 ft quanh lỗ để đếm số bóng dừng trong 3 ft sau mỗi bộ."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Xây dựng đường putt chắc chắn"],["o","Cải thiện khả năng putt vào ở cự ly gần"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tập đường gậy"],["s","5 phút tập đường gậy kéo thẳng ra sau, đẩy thẳng ra trước"],["h","2. Khởi động: cải thiện putt gần"],["s","Putt vào 50 bóng từ 2 feet"],["s","Putt vào 50 bóng từ 3 feet"],["s","Putt vào 50 bóng từ 4 feet"],["h","3. Cải thiện putt xa (lag)"],["s","30 cú putt từ 15 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 25 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 35 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Đặt một gậy sắt hoặc que căn hướng trên green tạo thành đường thẳng. Đưa putter lơ lửng phía trên và đánh sao cho đường gậy bám theo đường thẳng đó. Có thể đặt hai gậy song song tạo làn để putter đi giữa, như thanh chắn giữ đường gậy thẳng, giúp sửa đường gậy lệch hoặc giật."],["p","Bài 2: Đo 3 khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":2,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing nửa vòng với gậy sắt 6 (không bóng), tập trung đường swing từ trong ra ngoài."],["b","10 cú swing nửa vòng với gậy sắt 6, tập trung tiếp xúc bóng chắc"],["b","25 lần swing 3/4 với gậy sắt 6 (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing 3/4 với gậy sắt 6, tập trung tiếp xúc ổn định"],["b","25 lần swing toàn phần với gậy sắt 6 (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing toàn phần với gậy sắt 6, tập trung tiếp xúc chắc"],["p","Hướng dẫn: Với 3 bộ 10 cú đánh có bóng, nên đặt bóng trên tee để tiếp xúc tốt hơn. Tập trung tiếp xúc chắc với cú swing có kiểm soát, loại bỏ càng nhiều cú chunk càng tốt."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing nửa vòng không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với wedge, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách v