","Mục tiêu hôm nay:"],["o","Xây dựng đường putt chắc chắn"],["o","Cải thiện khả năng putt vào ở cự ly gần"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tập đường gậy: bài cổng 2 tee"],["s","25 lần đánh không bóng"],["s","25 cú putt vào lỗ từ 5 ft"],["h","2. Khởi động: cải thiện putt gần"],["s","Putt vào 50 bóng từ 2 feet"],["s","Putt vào 50 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["h","3. Cải thiện putt xa (lag)"],["s","30 cú putt từ 15 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 25 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","30 cú putt từ 35 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Cắm hai tee trên green cách lỗ 5 ft, khoảng cách giữa hai tee vừa đủ cho đầu putter đi qua. Hai tee là cái cổng bạn phải putt xuyên qua, buộc đường gậy phải thẳng để không chạm tee nào."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":4,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing nửa vòng với driver (không bóng), tập trung đường swing từ trong ra ngoài."],["b","10 cú swing nửa vòng với driver, tập trung tiếp xúc bóng chắc"],["b","25 lần swing 3/4 với driver (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing 3/4 với driver, tập trung tiếp xúc ổn định"],["b","25 lần swing toàn phần với driver (không bóng), tập trung đường swing từ trong ra ngoài"],["b","10 cú swing toàn phần với driver, tập trung tiếp xúc chắc"],["p","Hướng dẫn: Tập trung tiếp xúc chắc với cú swing có kiểm soát, loại bỏ càng nhiều cú chunk càng tốt. Nếu cả 10 cú swing toàn phần bằng driver đều đi ổn định từ 180 yard trở lên là bạn đang làm tốt. Mấy tuần đầu trọng tâm là tiếp xúc chắc để loại bỏ những cú chunk lãng phí."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing 3/4 không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 10 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với wedge, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách với wedge."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down từ rough (cách green 5 ft) bằng wedge chip"],["s","Hoàn thành 15 up & down tới lỗ gần (cách 10–15 ft)"],["s","Hoàn thành 15 up & down tới lỗ trung bình (cách 25–30 ft)"],["s","Hoàn thành 15 up & down tới lỗ xa (cách 35–40 ft trở lên)"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Putt trượt thì lượt đó không tính. Hoàn thành 15 lượt ở lỗ gần rồi chuyển sang 15 lượt ở lỗ trung bình và 15 lượt ở lỗ xa."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ rough"],["o","Cải thiện kiểm soát khoảng cách tới lỗ gần, trung bình và xa"],["o","Cải thiện khả năng chip bóng dừng trong 3 feet quanh lỗ"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough (cách mép green khoảng 5 ft)"],["s","50 cú chip tới lỗ gần (10–15 ft). Ghi số bóng dừng trong 3 feet quanh lỗ."],["s","50 cú chip tới lỗ trung bình (cách 25 ft). Ghi 