 tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 10 bóng với tốc độ swing chậm hơn (bóng đi khoảng 3/4 khoảng cách bình thường)"],["b","Đánh 10 bóng với tốc độ swing bình thường"],["b","Đánh 10 bóng với tốc độ swing nhanh hơn bình thường một chút"],["p","Hướng dẫn: Tập trung tiếp xúc chắc với cú swing có kiểm soát, loại bỏ càng nhiều cú chunk càng tốt. Nếu cả 10 cú swing toàn phần bằng driver đều đi ổn định từ 180 yard trở lên là bạn đang làm tốt. Mấy tuần đầu trọng tâm là tiếp xúc chắc để loại bỏ những cú chunk lãng phí. Ở bộ bóng cuối khi tăng tốc độ swing, đừng để mất kiểm soát."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing 3/4 không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 150 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 175 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down tới lỗ trung bình bằng wedge chip"],["s","50 lượt up & down từ fringe"],["s","50 lượt up & down từ rough (cách green 3 ft)"],["s","50 lượt up & down từ rough (cách green 5 ft)"],["p","Hướng dẫn: Dùng 10 bộ 5 bóng. Chip 5 bóng tới lỗ trung bình rồi putt mỗi bóng một lần vào lỗ để ghi một up & down. Đây là số lượt thử chứ không phải số lượt thành công: mỗi bài làm đủ 50 lượt và ghi số up & down thành công trên 50."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe và rough"],["o","Cải thiện cú bump & run (bay ít, lăn nhiều)"],["o","Cải thiện kiểm soát khoảng cách"],["p","Bài tập hôm nay:"],["h","1. Chip từ fringe"],["s","50 cú bump & run tới lỗ xa (40 ft trở lên)"],["s","50 cú chip thường tới lỗ xa (40 ft trở lên)"],["h","2. Chip từ rough (cách green 5 ft)"],["s","50 cú bump & run tới lỗ xa"],["s","50 cú chip thường tới lỗ xa"],["p","Tổng số cú chip hôm nay: 200"],["p","Hướng dẫn: Đánh 5 bộ 10 bóng hoặc 10 bộ 5 bóng để đủ 50 lượt cho mỗi bài trong 4 bài. Dùng mác bóng hoặc tee tạo vòng tròn bán kính 3 ft quanh lỗ để đếm số bóng dừng trong 3 ft sau mỗi bộ. Có thể dùng pitching wedge hoặc gậy sắt 9 cho cú bump & run."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Xây dựng đường putt chắc chắn"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tập đường gậy: putt một tay"],["s","25 lần đánh không bóng với mỗi tay (tổng 50 lần)"],["s","25 cú putt vào lỗ từ 3 ft với mỗi tay (tổng 50 lần)"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 75 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["h","3. Cải thiện putt xa (lag)"],["s","25 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 40 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","25 cú putt từ 50 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Có thể dùng lại dụng cụ căn hướng để giữ đường gậy thẳng, nhịp đều khi putt một tay. Putt một tay giúp cảm nhận mỗi tay kiểm soát mặt putter thế nào."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":6,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 10 bóng bằng driver"],["b","Đánh 10 bóng bằng gỗ fairway hoặc hybrid"],["b","Đánh 10 bóng bằng driver"],["p","Hướng dẫn: Tập trung tiếp xúc chắc cho cả 30 cú. Dùng hai loại gậy để có kỹ năng với cả hai, phòng khi có hố phải cất driver đi."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing 3/4 không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 150 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 175 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down tới lỗ xa bằng wedge chip"],["s","50 lượt up & down từ fringe"],["s","50 lượt up & down từ rough (cách green 3 ft)"],["s","50 lượt up & down từ rough (cách green 5 ft)"],["p","Hướng dẫn: Dùng 10 bộ 5 bóng. Chip 5 bóng tới lỗ xa rồi putt mỗi bóng một lần vào lỗ để ghi một up & down. Đây là số lượt thử chứ không phải số lượt thành công: mỗi bài làm đủ 50 lượt và ghi số up & down thành công trên 50."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện cú flop"],["o","Cải thiện kiểm soát khoảng cách tới lỗ xa từ fringe và rough"],["p","Bài tập hôm nay:"],["h","3. Chip từ fringe"],["s","50 cú flop (bóng bay cao, lăn ít) tới lỗ xa (40 ft trở lên)"],["s","50 cú chip thường tới lỗ xa"],["h","4. Chip từ rough (cách green 5 ft)"],["s","50 cú flop tới lỗ xa"],["s","50 cú chip thường tới lỗ xa"],["p","Tổng số cú chip hôm nay: 200 (100 flop, 100 chip thường)"],["p","Hướng dẫn: Đánh 5 bộ 10 bóng hoặc 10 bộ 5 bóng để đủ 50 lượt cho mỗi bài trong 4 bài. Dùng mác bóng hoặc tee tạo vòng tròn bán kính 3 ft quanh lỗ để đếm số bóng dừng trong 3 ft sau mỗi bộ. Cú flop dùng mặt gậy mở hoặc gậy độ loft cao để đánh bóng bay cao."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Xây dựng đường putt chắc chắn"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tập đường gậy: putt một tay"],["s","25 lần đánh không bóng với mỗi tay (tổng 50 lần)"],["s","25 cú putt vào lỗ từ 3 ft với mỗi tay (tổng 50 lần)"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 75 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["h","3. Cải thiện putt xa (lag)"],["s","25 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 40 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","25 cú putt từ 50 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Có thể dùng lại dụng cụ căn hướng để giữ đường gậy thẳng, nhịp đều khi putt một tay. Putt một tay giúp cảm nhận mỗi tay kiểm soát mặt putter thế nào."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":7,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 10 bóng bằng driver. Ghi số lần vào fairway (xem hướng dẫn)"],["b","Đánh 10 bóng bằng gỗ fairway hoặc hybrid. Ghi số lần vào fairway."],["b","Đánh 10 bóng bằng gậy sắt 4. Ghi số lần vào fairway."],["p","Hướng dẫn: Chọn một mục tiêu trên sân tập để nhắm cú phát bóng, dùng que căn hướng để vào tư thế. Hình dung 15 yard mỗi bên mục tiêu, tạo vùng rộng 30 yard. Cố đánh thẳng vào mục tiêu, nhưng bóng nằm trong vùng 30 yard thì tính là vào fairway. Ghi số cú thành công vào phiếu."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing 3/4 không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 150 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 175 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: 3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."]]},{"a":"scr","h":"Up & down (cứu par)","m":20,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Trò chơi up & down"],["s","Thử 18 lượt up & down (từng lượt một). Ghi điểm trên 18. Ngày 2 và ngày 3 phải vượt điểm này mới tính là qua bài."],["p","Hướng dẫn: Dùng một bóng. Chip tới các lỗ ở khoảng cách khác nhau để trò chơi ngẫu nhiên: khoảng 6 lượt tới lỗ gần, 6 lượt lỗ trung bình, 6 lượt lỗ xa trên green tập."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện khả năng chịu áp lực"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip liên tiếp dừng trong 3 ft: từ fringe"],["s","Chip liên tiếp 5 bóng dừng trong 3 ft quanh lỗ gần"],["s","Chip liên tiếp 5 bóng dừng trong 3 ft quanh lỗ trung bình"],["s","Chip liên tiếp 5 bóng dừng trong 3 ft quanh lỗ xa"],["p","Hướng dẫn: Dùng 5 bóng. Dùng mác bóng hoặc tee tạo vòng tròn bán kính 3 ft quanh lỗ để đếm sau mỗi bộ. Cả 5 bóng liên tiếp phải dừng trong 3 ft mới qua bài và chuyển sang khoảng cách tiếp theo."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực vòng tròn"],["s","Putt vào liên tiếp cả 5 bóng (một vòng quanh lỗ) từ 3 ft"],["s","Putt vào liên tiếp cả 5 bóng (một vòng quanh lỗ) từ 4 ft"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 50 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 50 bóng từ 6 feet"],["h","3. Cải thiện putt xa (lag)"],["s","25 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 40 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","25 cú putt từ 50 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Đo 3 ft từ 5 vị trí khác nhau quanh lỗ và cắm tee đánh dấu. Putt một bóng từ mỗi tee, đi vòng quanh lỗ, phải vào liên tiếp cả 5 mới qua. Sau đó lùi các tee ra thêm 1 foot thành 4 feet."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":8,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 10 bóng swing 3/4 bằng driver. Ghi số lần vào fairway (xem hướng dẫn)"],["b","Đánh 10 bóng swing 3/4 bằng gỗ fairway hoặc hybrid. Ghi số lần vào fairway."],["b","Đánh 10 bóng swing 3/4 bằng gậy sắt 4. Ghi số lần vào fairway."],["p","Hướng dẫn: Chọn một mục tiêu trên sân tập để nhắm cú phát bóng, dùng que căn hướng để vào tư thế. Hình dung 15 yard mỗi bên mục tiêu, tạo vùng rộng 30 yard. Cố đánh thẳng vào mục tiêu, nhưng bóng nằm trong vùng 30 yard thì tính là vào fairway. Ghi số cú thành công vào phiếu."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."],["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing 3/4 không bóng với wedge"],["b","10 lần swing toàn phần không bóng với wedge"],["b","Đánh 5 bóng tới mục tiêu 50 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 75 yard bằng wedge. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 100 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 125 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 150 yard. Ghi số lần vào green vào phiếu."],["b","Đánh 5 bóng tới mục tiêu 175 yard. Ghi số lần vào green vào phiếu."],["p","Hướng dẫn: Đây là tuần cuối tập bài này. 4 tuần cuối sẽ có bài khác."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down tới lỗ xa"],["s","Hoàn thành 10 up & down từ rough (cách green 15 ft)"],["s","Hoàn thành 15 up & down từ rough (cách green 10 ft)"],["s","Hoàn thành 20 up & down từ rough (cách green 5 ft)"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa. Hoàn thành đủ số up & down từ 3 vị trí khác nhau trong rough. Bài này giúp cứu par khi trượt green ở những khoảng khác nhau."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi chip"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough (cách 5 ft)"],["s","Đạt 20/25 cú chip dừng trong 3 ft ở lỗ gần mới qua"],["s","Đạt 20/25 cú chip dừng trong 3 ft ở lỗ trung bình mới qua"],["s","Đạt 15/25 cú chip dừng trong 3 ft ở lỗ xa mới qua"],["p","Hướng dẫn: Dùng 5 hoặc 10 bóng. Tạo vòng tròn bán kính 3 ft quanh lỗ bằng mác bóng hoặc tee. Chip từng bộ 5 hoặc 10 bóng, đếm số bóng dừng trong 3 ft, tiếp tục đến khi đủ 25 cú. Nếu chưa đạt 20/25 (80%) thì làm lại 25 cú khác cho tới khi đạt. Ở lỗ xa làm tương tự với chỉ tiêu 15/25."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực vòng tròn"],["s","Putt vào liên tiếp cả 5 bóng (một vòng quanh lỗ) từ 4 ft"],["s","Putt vào liên tiếp cả 5 bóng (một vòng quanh lỗ) từ 5 ft"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 50 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 50 bóng từ 6 feet"],["h","3. Cải thiện putt xa (lag)"],["s","25 cú putt từ 20 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 30 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","50 cú putt từ 40 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["s","25 cú putt từ 50 ft. Ghi số bóng dừng trong 3 ft quanh lỗ."],["p","Hướng dẫn:"],["p","Bài 1: Đo 4 ft từ 5 vị trí khác nhau quanh lỗ và cắm tee đánh dấu. Putt một bóng từ mỗi tee, đi vòng quanh lỗ, phải vào liên tiếp cả 5 mới qua. Sau đó lùi các tee ra thêm 1 foot thành 5 feet."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":9,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":40,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 7 bóng bằng driver. Ghi số lần vào fairway (xem hướng dẫn)"],["b","Đánh 7 bóng bằng gỗ fairway hoặc hybrid. Ghi số lần vào fairway."],["b","Đánh 7 bóng bằng gậy sắt 4. Ghi số lần vào fairway."],["b","Đánh 9 bóng bằng gậy tự chọn vào vùng fairway. Ghi số lần vào fairway."],["p","Hướng dẫn: Có vẻ lặp lại, nhưng mỗi tuần bạn phải vượt chỉ số tuần trước bằng cách tập trung, vào fairway nhiều hơn và bớt cú hỏng. Chọn mục tiêu trên sân tập, dùng que căn hướng để vào tư thế, dựng vùng fairway rộng 30 yard để đánh vào."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."],["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing không bóng với gậy sắt 7, 8 và 9"],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 7. Ghi số lần vào green."],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 8. Ghi số lần vào green."],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 9. Ghi số lần vào green."],["b","Làm lại lượt thứ 2, cố vượt điểm với cả 3 gậy."],["p","Hướng dẫn: Chọn mục tiêu trên sân tập gần đúng khoảng cách bạn đánh gậy sắt 7, 8 và 9. Nếu quanh mục tiêu không có green thì hình dung một green rộng 10 yard, dài 10 yard, mục tiêu ở giữa. Ghi số GIR vào phiếu."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down bằng một gậy bạn chưa từng dùng để chip"],["s","Hoàn thành 10 up & down tới lỗ gần"],["s","Hoàn thành 10 up & down tới lỗ trung bình"],["s","Hoàn thành 10 up & down tới lỗ xa"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa. Hoàn thành đủ số up & down của từng bài. Thành thạo thêm một gậy sẽ cho bạn thêm cú đánh để dùng khi cần trên sân."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi chip"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough (cách 5 ft)"],["s","Đạt 24/25 cú chip dừng trong 3 ft ở lỗ gần mới qua"],["s","Đạt 22/25 cú chip dừng trong 3 ft ở lỗ trung bình mới qua"],["s","Đạt 20/25 cú chip dừng trong 3 ft ở lỗ xa mới qua"],["p","Hướng dẫn: Dùng 5 hoặc 10 bóng. Tạo vòng tròn bán kính 3 ft quanh lỗ bằng mác bóng hoặc tee. Chip từng bộ 5 hoặc 10 bóng, đếm số bóng dừng trong 3 ft, tiếp tục đến khi đủ 25 cú. Nếu chưa đạt 24/25 thì làm lại 25 cú khác cho tới khi đạt. Ở lỗ xa làm tương tự với chỉ tiêu 20/25."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực vòng tròn"],["s","Putt vào liên tiếp cả 10 bóng (hai vòng quanh lỗ) từ 4 ft"],["s","Putt vào liên tiếp cả 10 bóng (hai vòng quanh lỗ) từ 5 ft"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 100 bóng từ 3 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["s","Putt vào 50 bóng từ 7 feet"],["h","3. Cải thiện putt xa (lag)"],["s","Đạt 20/25 cú putt dừng trong 3 ft từ 50 feet"],["s","Đạt 22/25 cú putt dừng trong 3 ft từ 40 feet"],["s","Đạt 24/25 cú putt dừng trong 3 ft từ 20 feet"],["p","Hướng dẫn:"],["p","Bài 1: Đo 4 ft từ 5 vị trí khác nhau quanh lỗ và cắm tee đánh dấu. Putt một bóng từ mỗi tee, đi vòng quanh lỗ, phải vào liên tiếp cả 5 bóng hai lần mới qua. Sau đó lùi các tee ra thêm 1 foot thành 5 feet."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":10,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 5 bóng quỹ đạo cao bằng driver. Ghi số cú đúng quỹ đạo."],["b","Đánh 5 bóng quỹ đạo cao bằng gỗ fairway. Ghi số cú đúng quỹ đạo."],["b","Đánh 5 bóng quỹ đạo thấp bằng driver. Ghi số cú đúng quỹ đạo."],["b","Đánh 5 bóng quỹ đạo thấp bằng gỗ fairway. Ghi số cú đúng quỹ đạo."],["b","Đánh 10 bóng cao và thấp bằng gậy tự chọn. Ghi số cú đúng quỹ đạo."],["p","Hướng dẫn: Hôm nay tập tăng khoảng bay của cú drive bằng cách đánh bóng bay cao hơn. Đồng thời tập cú bay thấp (stinger) với driver và gỗ để xử lý khi gió to hoặc vướng cành cây. Ghi số cú bay đúng quỹ đạo bạn định đánh. Dịch bóng lên trước hoặc lùi ra sau trong thế đứng để thay đổi quỹ đạo."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","3 mục tiêu lớn: (1) tiếp xúc chắc với các gậy, (2) đánh càng thẳng càng tốt, và khi làm được cả hai thì (3) kiểm soát khoảng cách thật chuẩn."],["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing không bóng với gậy sắt 7, 8 và 9"],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 7. Ghi số lần vào green."],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 8. Ghi số lần vào green."],["b","Đánh 5 bóng vào green mục tiêu bằng gậy sắt 9. Ghi số lần vào green."],["b","Làm lại lượt thứ 2, cố vượt điểm với cả 3 gậy."],["p","Hướng dẫn: Chọn mục tiêu trên sân tập gần đúng khoảng cách bạn đánh gậy sắt 7, 8 và 9. Nếu quanh mục tiêu không có green thì hình dung một green rộng 10 yard, dài 10 yard, mục tiêu ở giữa. Ghi số GIR vào phiếu."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down bằng một gậy bạn chưa từng dùng để chip"],["s","Hoàn thành 10 up & down tới lỗ gần"],["s","Hoàn thành 10 up & down tới lỗ trung bình"],["s","Hoàn thành 10 up & down tới lỗ xa"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa. Hoàn thành đủ số up & down của từng bài. Thành thạo thêm một gậy sẽ cho bạn thêm cú đánh để dùng khi cần trên sân. Không dùng lại gậy đã dùng ở tuần 9."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi chip"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough (cách 5 ft)"],["s","25 cú bump & run tới lỗ xa"],["s","25 cú flop tới lỗ trung bình"],["s","25 cú chip thường tới lỗ gần"],["s","25 cú chip luân phiên kiểu cú và lỗ"],["p","Hướng dẫn: Dùng 5 hoặc 10 bóng. Tạo vòng tròn bán kính 3 ft quanh lỗ bằng mác bóng hoặc tee để đếm sau mỗi bộ. Chip từng bộ 5 hoặc 10 bóng và đếm số bóng dừng trong 3 ft."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực"],["s","Putt vào liên tiếp 25 bóng từ 3 feet"],["s","Putt vào liên tiếp 15 bóng từ 4 feet"],["s","Putt vào liên tiếp 5 bóng từ 5 feet"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["s","Putt vào 25 bóng bẻ trái từ 7 feet"],["s","Putt vào 25 bóng bẻ phải từ 7 feet"],["h","3. Cải thiện putt xa (lag)"],["s","Đạt 20/25 cú putt dừng trong 3 ft từ 50 feet"],["s","Đạt 22/25 cú putt dừng trong 3 ft từ 40 feet"],["s","Đạt 24/25 cú putt dừng trong 3 ft từ 20 feet"],["p","Hướng dẫn:"],["p","Bài 1: Chọn các điểm cách lỗ 3 ft, 4 ft và 5 ft, cắm tee đánh dấu. Putt vào liên tiếp đủ số bóng yêu cầu ở mỗi khoảng cách, qua thì chuyển sang khoảng cách tiếp theo."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":11,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","10 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 5 bóng draw bằng driver. Ghi số cú đúng."],["b","Đánh 5 bóng draw bằng gỗ fairway. Ghi số cú đúng."],["b","Đánh 5 bóng fade bằng driver. Ghi số cú đúng."],["b","Đánh 5 bóng fade bằng gỗ fairway. Ghi số cú đúng."],["b","Đánh 10 bóng thẳng nhất có thể bằng driver. Ghi số cú đúng."],["p","Hướng dẫn: Hôm nay học cách điều hướng bóng với draw và fade. Tập từng kiểu với driver và gỗ fairway. Nếu chưa biết cách đánh đúng từng kiểu, hãy xem video hướng dẫn trước khi ra sân tập."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing không bóng với gậy sắt 7, tập trung nhịp swing và đường swing"],["b","5 cú tới mục tiêu 100 yard"],["b","5 cú tới mục tiêu 150 yard"],["b","5 cú tới mục tiêu 200 yard"],["b","5 cú draw bằng gậy sắt 7"],["b","5 cú fade bằng gậy sắt 7"],["b","5 cú thẳng bằng gậy sắt 7"],["p","Hướng dẫn: Chọn 3 gậy gần đúng với mục tiêu 100, 150 và 200 yard. Ghi số lần vào green. Sau đó tập draw, fade và cú thẳng bình thường bằng gậy sắt 7 vào mục tiêu."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down bằng wedge chip quen dùng từ rough (cách green 10 ft)"],["s","Hoàn thành 20 up & down tới lỗ gần"],["s","Hoàn thành 20 up & down tới lỗ trung bình"],["s","Hoàn thành 20 up & down tới lỗ xa"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa. Hoàn thành đủ số up & down của từng bài. Đến giờ bạn hẳn đã thành thạo up & down từ xa green khi trượt 5–10 yard. Chọn một điểm trong rough cách green 15–20 ft để làm up & down. Cố gắng hết sức!"]]},{"a":"chip","h":"Chip","m":25,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ xa green"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough (cách 20 ft)"],["s","25 cú chip tới lỗ gần (có thể phải dùng cú flop bay cao)"],["s","25 cú chip tới lỗ trung bình (có thể phải dùng cú flop bay cao)"],["s","25 cú chip tới lỗ xa ở phía bên kia green tập"],["p","Hướng dẫn: Dùng 5 hoặc 10 bóng. Tập chip về lỗ khi đứng xa green (20 ft trong rough). Chọn lỗ không làm phiền người khác đang dùng green tập. Tạo vòng tròn bán kính 3 ft quanh lỗ bằng mác bóng hoặc tee. Chip từng bộ 5 hoặc 10 bóng và đếm số bóng dừng trong 3 ft."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện khả năng putt đường bẻ"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực"],["s","Putt vào liên tiếp 25 bóng từ 3 feet"],["s","Putt vào liên tiếp 15 bóng từ 4 feet"],["s","Putt vào liên tiếp 5 bóng từ 5 feet"],["h","2. Cải thiện putt gần và putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["s","Putt vào 25 bóng bẻ trái từ 7 feet"],["s","Putt vào 25 bóng bẻ phải từ 7 feet"],["h","3. Cải thiện putt xa (lag)"],["s","Đạt 20/25 cú putt dừng trong 3 ft từ 50 feet"],["s","Đạt 22/25 cú putt dừng trong 3 ft từ 40 feet"],["s","Đạt 24/25 cú putt dừng trong 3 ft từ 20 feet"],["p","Hướng dẫn:"],["p","Bài 1: Chọn các điểm cách lỗ 3 ft, 4 ft và 5 ft, cắm tee đánh dấu. Putt vào liên tiếp đủ số bóng yêu cầu ở mỗi khoảng cách, qua thì chuyển sang khoảng cách tiếp theo."],["p","Bài 2: Đo các khoảng cách bằng giày (khoảng 1 foot) hoặc putter (khoảng 3 ft), đánh dấu bằng tee hoặc mác bóng. Sau đó dùng bộ 5 hoặc 10 bóng và bắt đầu putt vào lỗ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]},{"w":12,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","25 lần swing tập không bóng với driver, tập trung đường swing từ trong ra ngoài"],["b","Đánh 5 bóng draw bằng driver. Ghi số cú đúng."],["b","Đánh 5 bóng fade bằng driver. Ghi số cú đúng."],["b","Đánh 5 bóng quỹ đạo cao bằng driver. Ghi số cú đúng."],["b","Đánh 5 bóng quỹ đạo thấp bằng driver. Ghi số cú đúng."],["b","Đánh 10 cú drive bình thường bằng driver. Ghi số lần vào fairway."],["p","Hướng dẫn: Chào mừng đến tuần 12. Tuần cuối trên sân tập gồm draw, fade, quỹ đạo cao thấp và cú drive bình thường. Hết tuần này bạn sẽ có cảm giác tốt với từng kiểu cú và có thể tiếp tục tập ở các tuần sau."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing không bóng với gậy sắt 7, tập trung nhịp swing và đường swing"],["b","5 cú tới mục tiêu 50 yard"],["b","5 cú tới mục tiêu 125 yard"],["b","5 cú tới mục tiêu 175 yard"],["b","5 cú draw bằng gậy sắt 5"],["b","5 cú fade bằng gậy sắt 5"],["b","5 cú thẳng bằng gậy sắt 5"],["p","Hướng dẫn: Chọn 3 gậy gần đúng với mục tiêu 50, 125 và 175 yard. Ghi số lần vào green. Sau đó tập draw, fade và cú thẳng bình thường bằng gậy sắt 5 vào mục tiêu."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down bằng wedge chip quen dùng từ rough (cách green 15 ft)"],["s","Hoàn thành 20 up & down tới lỗ gần"],["s","Hoàn thành 10 up & down tới lỗ trung bình"],["s","Hoàn thành 10 up & down tới lỗ xa"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa. Hoàn thành đủ số up & down của từng bài. Đến giờ bạn hẳn đã thành thạo up & down từ xa green khi trượt 5–10 yard. Chọn một điểm trong rough cách green 15–20 ft để làm up & down. Hãy tận hưởng tuần cuối cùng hoàn thiện kỹ năng cứu par."]]},{"a":"chip","h":"Chip","m":25,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ các khoảng cách khác nhau ngoài green"],["o","Cải thiện kiểm soát khoảng cách và độ ổn định"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough"],["s","25 cú chip tới lỗ tự chọn từ rough (cách green 15 ft)"],["s","25 cú chip tới lỗ tự chọn từ rough (cách green 25 ft)"],["s","25 cú chip tới lỗ tự chọn từ rough (cách green 10 ft)"],["p","Hướng dẫn: Dùng 5 hoặc 10 bóng. Tập chip về lỗ khi đứng xa green (10–25 ft trong rough). Chọn lỗ không làm phiền người khác đang dùng green tập. Tạo vòng tròn bán kính 3 ft quanh lỗ bằng mác bóng hoặc tee. Chip từng bộ 5 hoặc 10 bóng và đếm số bóng dừng trong 3 ft."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện bản lĩnh khi putt"],["o","Cải thiện putt xuống dốc"],["o","Cải thiện putt xa (lag) để giảm số lần 3 putt"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Tâm lý: putt áp lực"],["s","Putt vào liên tiếp 25 bóng từ 3 feet"],["s","Putt vào liên tiếp 20 bóng từ 4 feet"],["s","Putt vào liên tiếp 10 bóng từ 5 feet"],["h","2. Cải thiện putt xuống dốc cự ly gần"],["s","Putt vào 25 bóng xuống dốc từ 5 feet."],["s","Putt vào 3 bóng xuống dốc từ 9 feet."],["h","3. Cải thiện putt xa (lag)"],["s","10/10 cú putt dừng trong 3 ft từ 15 ft"],["s","10/10 cú putt dừng trong 3 ft từ 25 ft"],["s","10/10 cú putt dừng trong 3 ft từ 35 ft"],["p","Hướng dẫn:"],["p","Bài 1: Chọn các điểm cách lỗ 3 ft, 4 ft và 5 ft, cắm tee đánh dấu. Putt vào liên tiếp đủ số bóng yêu cầu ở mỗi khoảng cách, qua thì chuyển sang khoảng cách tiếp theo."],["p","Bài 2: Chọn một lỗ trên green tập và tìm phía có đường putt xuống dốc. Đo 5 ft và cắm tee đánh dấu, putt vào 25 bóng từ đó. Có thể đánh dấu vài vị trí xuống dốc khác nhau để đổi đường putt. Sau đó làm lại từ 9 feet, putt vào 3 bóng. Tập trung kiểm soát tốc độ."],["p","Bài 3: Dùng putter (khoảng 3 ft) và mác bóng tạo vòng tròn bán kính 3 ft quanh lỗ. Putt đủ số lượt ở mỗi khoảng cách, cố đưa bóng dừng trong vòng 3 ft."]]}]}],"b80":[{"w":1,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","Đánh 7 bóng bằng driver. Ghi số lần vào fairway."],["b","Đánh 7 bóng bằng gỗ fairway. Ghi số lần vào fairway."],["b","Đánh 7 bóng bằng driver. Ghi số lần vào fairway."],["b","Đánh 7 bóng bằng gỗ fairway. Ghi số lần vào fairway."],["p","Hướng dẫn: Chọn mục tiêu trên sân tập và đặt que căn hướng để vào tư thế cho từng cú. Hình dung vùng fairway rộng 30 yard, mỗi bên mục tiêu 15 yard, đánh như đang cố vào fairway trên sân. Ghi số cú nằm trong vùng fairway tưởng tượng. Các ngày tập sau (ngày 2, ngày 3) phải vượt con số này."]]},{"a":"gir","h":"Green (GIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","Đánh 10 bóng tới mục tiêu 100 yard. Ghi số GIR."],["b","Đánh 10 bóng tới mục tiêu 150 yard. Ghi số GIR."],["b","Đánh 10 bóng tới mục tiêu 125 yard. Ghi số GIR."],["p","Hướng dẫn: Căn hướng tới 3 mục tiêu khác nhau bằng que căn hướng hoặc gậy đặt dưới đất. Nếu sân tập chỉ có cột mốc thì hình dung một green. Ghi số cú sẽ vào green nếu đang trên sân thật. Ngày 2 và ngày 3 phải vượt con số này."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down từ rough quanh green bằng wedge quen dùng"],["s","Hoàn thành 30 up & down tới lỗ gần (cách khoảng 10 ft)"],["s","Hoàn thành 20 up & down tới lỗ trung bình (cách khoảng 25 ft)"],["s","Hoàn thành 10 up & down tới lỗ xa (cách khoảng 40 ft)"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe và rough quanh green"],["o","Cải thiện kiểm soát khoảng cách tới lỗ gần, trung bình và xa"],["o","Cải thiện khả năng chip bóng dừng trong 3 feet quanh lỗ"],["p","Bài tập hôm nay:"],["h","1. Chip từ fringe"],["s","50 cú chip từ fringe tới lỗ xa (40 ft trở lên). Ghi số bóng dừng trong 3 feet quanh lỗ. Ngày 2 và ngày 3 phải vượt con số này."],["h","2. Rough quanh green (cách mép green 5 ft)"],["s","50 cú chip tới lỗ trung bình (cách 25 ft). Ghi số bóng dừng trong 3 feet quanh lỗ. Ngày 2 và ngày 3 phải vượt con số này."],["h","3. Chip cự ly ngắn"],["s","Đạt 50 cú chip dừng trong 3 feet ở lỗ gần (10–15 ft)"],["p","Hướng dẫn: Đánh theo bộ 10 hoặc 5 bóng. Ghi kết quả vào phiếu."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Putt bẻ trái và bẻ phải từ nhiều khoảng cách"],["o","Putt áp lực"],["o","Putt xa (lag)"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Cải thiện putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["h","3. Putt áp lực: vào liên tiếp"],["s","Putt vào liên tiếp 5 bóng từ 4 feet. Tự chọn kiểu đường (phẳng, bẻ trái, bẻ phải)"],["s","Putt vào liên tiếp 5 bóng từ 5 feet. Tự chọn kiểu đường (phẳng, bẻ trái, bẻ phải)"],["h","4. Putt xa (lag)"],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 25 feet. Làm lại nếu quá 10 bóng không dừng trong 3 feet."],["s","Lag 40/50 bóng từ 35 feet. Làm lại nếu quá 10 bóng không dừng trong 3 feet."],["p","Hướng dẫn: Dùng mác bóng tạo vùng 3 foot quanh lỗ làm đích cho putt xa. Phải đạt 40/50 bóng dừng trong vùng, nếu không thì làm lại từ khoảng cách đó."]]}]},{"w":2,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","14 bóng vào mục tiêu bằng driver. Ghi số lần vào fairway, trượt trái và trượt phải."],["b","Đánh 2 bóng bằng gậy sắt 4 vào vùng fairway để nghỉ driver một chút"],["b","Đánh 14 bóng vào mục tiêu bằng driver. Ghi số lần vào fairway, trượt trái và trượt phải."],["p","Hướng dẫn: Hôm nay lại tập đánh vào vùng fairway rộng 30 yard tự hình dung trên sân tập. Đánh 14 cú drive mô phỏng 14 lần phát bóng trên sân, xem bao nhiêu cú vào fairway. Ghi cả các cú trượt để biết mình hay trượt trái hay phải. Cuối tuần so kết quả cả 3 ngày tập."]]},{"a":"gir","h":"Green (GIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","Đánh 3 bóng bằng gậy sắt 9 tới mục tiêu gần đúng khoảng cách gậy sắt 9"],["b","Đánh 3 bóng bằng gậy sắt 7 tới mục tiêu gần đúng khoảng cách gậy sắt 7"],["b","Đánh 3 bóng bằng gậy sắt 8 tới mục tiêu gần đúng khoảng cách gậy sắt 8"],["b","Đánh 3 bóng bằng gậy sắt 6 tới mục tiêu gần đúng khoảng cách gậy sắt 6"],["b","Đánh 3 bóng bằng gậy sắt 4 tới mục tiêu gần đúng khoảng cách gậy sắt 4"],["b","Đánh 3 bóng bằng gậy sắt 5 tới mục tiêu gần đúng khoảng cách gậy sắt 5"],["b","Đánh 12 cú wedge tới mục tiêu 50–80 yard, tập cả swing toàn phần và nửa vòng."],["p","Hướng dẫn: Mỗi gậy chỉ đánh 3 bóng nên hãy tập trung từng cú, không vội. Ghi số GIR của từng gậy trong 6 gậy."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down áp lực"],["s","Hoàn thành liên tiếp 10 up & down tới lỗ gần"],["s","Hoàn thành liên tiếp 5 up & down tới lỗ trung bình"],["s","Hoàn thành liên tiếp 5 up & down tới lỗ xa"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Đánh từ rough quanh green."]]},{"a":"chip","h":"Chip","m":60,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát điểm rơi"],["o","Cải thiện cú flop và bump & run"],["p","Bài tập hôm nay:"],["h","1. Tập điểm rơi"],["s","Chip trúng khăn gấp đặt cách 15 feet đủ 20 lần. Chip từ fringe."],["s","Chip trúng khăn gấp đặt cách 15 feet đủ 20 lần. Chip từ rough quanh green."],["h","2. Chip dừng trong 3 feet từ rough quanh green"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ gần"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ xa"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ trung bình"],["h","3. Flop và bump & run"],["s","20 cú chip tới lỗ cách 40 ft bằng kỹ thuật flop"],["s","20 cú chip tới lỗ cách 40 ft bằng kỹ thuật bump & run"],["p","Hướng dẫn: Gấp một chiếc khăn thành mục tiêu nhỏ, đặt trên green tập cách bạn 15 feet. Chip sao cho bóng rơi trúng khăn."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt 3 feet ổn định"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt từ fringe"],["s","50 cú putt từ fringe tới lỗ gần"],["s","50 cú putt từ fringe tới lỗ trung bình"],["s","50 cú putt từ fringe tới lỗ xa"],["h","3. Putt xa (lag)"],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["h","4. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"]]}]},{"w":3,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","5 bóng driver swing nửa vòng"],["b","5 bóng driver swing 3/4"],["b","5 bóng driver swing toàn phần"],["b","5 bóng gỗ fairway swing nửa vòng"],["b","5 bóng gỗ fairway swing 3/4"],["b","5 bóng gỗ fairway swing toàn phần"],["p","Hướng dẫn: Dùng cảm giác để nhận ra nhịp của từng kiểu swing. Giữ swing mượt và có kiểm soát."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 bóng đặt trên tee với gậy sắt 6"],["b","5 bóng đặt trên tee với gậy sắt 7"],["b","10 bóng với gậy đánh 125 yard. Ghi số GIR"],["b","10 bóng với gậy đánh 100 yard. Ghi số GIR"],["p","Hướng dẫn: Đánh bóng đặt trên tee để mô phỏng cú phát bóng hố par 3, đồng thời tập tiếp xúc mượt và tạo tự tin. Sau đó đánh vào mục tiêu với gậy 125 yard và gậy 100 yard, ghi số lần sẽ vào green nếu đang trên sân. Mỗi ngày tập sau cố vượt số GIR."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Khối lượng lớn từ rough quanh green"],["s","Hoàn thành 100 up & down tới các lỗ tự chọn ngẫu nhiên trên green tập."],["p","Hướng dẫn: Dùng bộ 5 bóng cho nhanh, vì dùng một bóng sẽ rất lâu. (Ví dụ: chip 5 bóng, putt cả 5, vào 3 thì còn 97 up & down. Chip tiếp 5 bóng, putt, trừ số bóng vào khỏi 97.)"]]},{"a":"chip","h":"Chip","m":30,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách"],["o","Tập trung đưa bóng dừng trong 3 feet để putt dễ"],["p","Bài tập hôm nay:"],["h","1. Kiểm soát khoảng cách"],["s","Chip 50 bóng (5 bộ 10) tới lỗ xa. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ trung bình. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ gần. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["p","Hướng dẫn: Cuối tuần so kết quả và tỉ lệ của cả 3 ngày tập."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["h","3. Putt từ fringe"],["s","50 cú putt từ fringe tới lỗ xa"],["h","4. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."]