 cách"],["s","Chip 50 bóng (5 bộ 10) tới lỗ xa. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ trung bình. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ gần. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["h","2. Chip vui"],["s","Chip 50 bóng tới lỗ gần (cách 10 ft trở xuống), đếm số bóng chip vào lỗ trên 50. Ngày 2 và ngày 3 cố vượt con số này."],["p","Hướng dẫn: Cuối tuần so kết quả và tỉ lệ của cả 3 ngày tập."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["h","3. Putt từ fringe"],["s","Đạt 40/50 cú putt từ fringe tới lỗ trung bình hoặc xa dừng trong 3 feet quanh lỗ mới qua."],["s","25 cú putt từ fringe tới lỗ gần. Ghi số bóng vào lỗ vào phiếu."],["h","4. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["h","5. Putt áp lực"],["s","Putt vào liên tiếp 20 bóng từ 3 feet"],["s","Putt vào liên tiếp 10 bóng từ 4 feet"]]}]},{"w":5,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","10 cú draw bằng driver"],["b","10 cú draw bằng gỗ fairway"],["b","10 cú draw bằng driver"],["p","Hướng dẫn: Sau 4 tuần tập vào fairway với nhiều gậy và chú trọng độ chính xác, đã đến lúc đổi mới và thêm kỹ năng. Tuần này chỉ tập cú draw với driver và gỗ fairway. Đừng quan tâm bao nhiêu cú vào fairway, chỉ tập trung làm bóng cong theo ý mình."],["p","Nếu chưa biết cách đánh draw (điều này bình thường), hãy dành thời gian xem video hướng dẫn trước khi ra sân. YouTube có nhiều video hay, cũng có nhiều bài viết giải thích chi tiết cú draw. Nên nhờ HLV swing ở sân giúp học cú draw và cú fade, là trọng tâm của tuần sau."]]},{"a":"gir","h":"Green (GIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 cú draw bằng gậy sắt 5"],["b","10 cú draw bằng gậy sắt 6"],["b","10 cú thẳng, bình thường bằng gậy sắt 7"],["p","Hướng dẫn: Tập draw với hai gậy sắt dài, rồi quay lại đánh cú bình thường bằng gậy sắt 7 để lấy lại cảm giác cú thẳng."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down áp lực từ rough quanh green"],["s","Hoàn thành liên tiếp 20 up & down tới lỗ gần"],["s","Hoàn thành liên tiếp 5 up & down tới lỗ trung bình"],["s","Hoàn thành liên tiếp 5 up & down tới lỗ xa"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát cú flop"],["o","Cải thiện kiểm soát khoảng lăn"],["o","Cải thiện kiểm soát khoảng bay và điểm rơi"],["p","Bài tập hôm nay:"],["h","1. Cú flop"],["s","50 cú flop (bay cao, rơi mềm) tới lỗ cách 40 ft. Ghi số bóng dừng trong 3 feet quanh lỗ"],["h","2. Chip áp lực"],["s","Đạt 10/10 bóng dừng trong 3 feet khi chip từ rough quanh green tới lỗ cách 20 ft"],["h","3. Chip từ xa green: cách mép green 20 ft"],["s","50 cú chip (5 bộ 10) tới lỗ ở giữa green tập"],["p","Hướng dẫn: Chọn một điểm trong rough cách green khoảng 20 feet (7 bước dài) để mô phỏng trượt green 5–10 yard. Chip từ đó lên green tới lỗ gần giữa green tập để có khoảng dừng bóng. Có thể cần gậy loft cao để bóng dừng nhanh hơn. Có thể thử thêm vài cú flop."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Putt xa dưới áp lực"],["o","Putt gần dưới áp lực"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt xa (lag)"],["s","Lag 49/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","Lag 47/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 50 feet. Không đạt thì làm lại."],["h","3. Putt áp lực: bài vòng tròn"],["s","Putt vào liên tiếp 10 bóng (2 vòng quanh lỗ) từ 4 feet"]]}]},{"w":6,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","10 cú fade bằng driver"],["b","10 cú fade bằng gỗ fairway"],["b","10 cú fade bằng driver"],["p","Hướng dẫn: Tuần này chỉ tập cú fade với driver và gỗ fairway. Đừng quan tâm bao nhiêu cú vào fairway, chỉ tập trung làm bóng cong theo ý mình."],["p","Nếu chưa biết cách đánh fade (điều này bình thường), hãy dành thời gian xem video hướng dẫn trước khi ra sân. YouTube có nhiều video hay, cũng có nhiều bài viết giải thích chi tiết cú fade. Nên nhờ HLV swing ở sân giúp học cú draw và cú fade."]]},{"a":"gir","h":"Green (GIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 cú fade bằng gậy sắt 5"],["b","10 cú fade bằng gậy sắt 6"],["b","10 cú bình thường bằng gậy sắt 7"],["p","Hướng dẫn: Tuần này tập fade xen với cú bình thường để không mất cảm giác cú thẳng sau một tuần thay đổi hướng bóng."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Tập lên dốc và xuống dốc từ rough quanh green"],["s","Hoàn thành tổng cộng 50 up & down tới các lỗ tự chọn"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách"],["o","Cải thiện khả năng chịu áp lực"],["o","Cải thiện cú bump & run"],["p","Bài tập hôm nay:"],["h","1. Chip khối lượng lớn, dừng trong 3 ft"],["s","Chip 25 bóng dừng trong 3 feet ở lỗ trung bình"],["s","Chip 25 bóng dừng trong 3 feet ở lỗ xa"],["s","Chip 25 bóng dừng trong 3 feet ở lỗ xuống dốc. Tự chọn khoảng cách, vì lỗ xuống dốc ở mỗi green tập mỗi khác."],["h","2. Chip áp lực"],["s","Đạt 15/15 bóng dừng trong 3 feet khi chip từ fringe tới lỗ cách 10 ft"],["h","3. Bump & run"],["s","50 cú chip tới các lỗ tự chọn, thay đổi khoảng cách cú bump & run"],["s","Đánh phần lớn từ rough, một số từ fringe để đổi thế bóng"],["p","Hướng dẫn: Nếu green tập không có dốc, mọi cú putt và chip đều phẳng, thì đành thay các bài chip lên dốc và xuống dốc bằng chip phẳng bình thường."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["s","Putt vào 25 bóng bẻ trái từ 7 feet"],["s","Putt vào 25 bóng bẻ phải từ 7 feet"],["h","3. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 60 feet."],["h","4. Bài thẳng hàng: cắm tee ở 3 ft, 6 ft, 9 ft trên một đường thẳng"],["s","Putt vào liên tiếp cả 3 bóng, mỗi tee một bóng, mới qua bài"],["s","Nếu còn thời gian và muốn thử thách, làm theo thứ tự ngược lại"],["p","Hướng dẫn: Hôm nay thử putt xa 60 foot như ở bài 3. Nếu green tập ở sân không đủ rộng thì putt từ khoảng xa nhất có thể."]]}]},{"w":7,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","10 bóng thẳng nhất có thể bằng driver. Ghi số cú thành công."],["b","10 bóng draw bằng driver. Ghi số cú thành công."],["b","10 bóng fade bằng driver. Ghi số cú thành công."],["p","Hướng dẫn: Đánh 10 bóng cho mỗi kiểu hướng bóng và ghi số cú cong đúng ý. Chưa cần quan tâm bóng có rơi vào fairway không, chỉ xem có đánh được draw, fade hoặc thẳng không."]]},{"a":"gir","h":"Green (GIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 cú swing 3/4 vào mục tiêu bằng gậy sắt 7"],["b","5 cú swing toàn phần vào mục tiêu bằng gậy sắt 7"],["b","5 cú swing 3/4 vào mục tiêu bằng gậy sắt 8"],["b","5 cú swing toàn phần vào mục tiêu bằng gậy sắt 8"],["b","5 cú swing 3/4 vào mục tiêu bằng gậy sắt 9"],["b","5 cú swing toàn phần vào mục tiêu bằng gậy sắt 9"],["b","Ngày tập 2 dùng gậy sắt 4, 5, 6"],["b","Ngày tập 3 dùng gậy sắt 9, wedge thứ nhất, wedge thứ hai"],["p","Hướng dẫn: Tập swing 3/4 và swing toàn phần với tất cả gậy sắt và wedge để có cảm giác dùng một gậy cho nhiều khoảng cách. Tình huống này có thể gặp trong vòng đấu khi có gió hoặc chướng ngại, phải swing 3/4 với gậy lớn hơn hoặc nhỏ hơn một số. Một hai tuần tới cũng sẽ tập thêm wedge. Bạn nên có hai hoặc ba wedge, dùng hai cái cho bài này. Ví dụ: pitching wedge, sand wedge, 54 độ, 56 độ, 60 độ."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Tập lên dốc và xuống dốc từ rough quanh green"],["s","Hoàn thành liên tiếp 10 up & down từ 4 phía khác nhau của green tập tới cùng một lỗ tự chọn. Chỉ chuyển vị trí khi đã đạt 10 lượt liên tiếp ở vị trí hiện tại."],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Đừng tự lừa mình."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát cú flop"],["o","Cải thiện kiểm soát khoảng cách"],["o","Cải thiện kiểm soát điểm rơi"],["p","Bài tập hôm nay:"],["h","1. Cú flop"],["s","50 cú chip tới lỗ cách 40 ft. Ghi số bóng dừng trong 3 feet quanh lỗ"],["h","2. Chip áp lực"],["s","Đạt 15/15 bóng dừng trong 3 feet khi chip từ rough quanh green tới lỗ cách 20 ft"],["h","3. Tập điểm rơi"],["s","Chip trúng khăn gấp đặt cách 15 feet đủ 20 lần"],["p","Hướng dẫn: Gấp một chiếc khăn thành mục tiêu nhỏ, đặt trên green tập cách bạn 15 feet. Chip sao cho bóng rơi trúng khăn. Có thể đánh cả từ rough và fringe để quen cả hai thế bóng."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt áp lực: trò chơi 18 hố (xem hướng dẫn bên dưới)"],["s","6 cú putt từ 4 ft đến 10 ft"],["s","6 cú putt từ 11 ft đến 25 ft"],["s","6 cú putt từ 25 ft đến 50 ft"],["s","Ghi điểm và vượt điểm đó mỗi ngày (ngày tập 2 và 3)"],["h","3. Putt từ fringe"],["s","50 cú putt từ fringe tới lỗ gần"],["s","50 cú putt từ fringe tới lỗ trung bình"],["s","50 cú putt từ fringe tới lỗ xa"],["h","4. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["h","5. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"]]}]},{"w":8,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","10 lần swing nhẹ không bóng với driver (tốc độ swing chậm)"],["b","10 lần swing bình thường không bóng với driver"],["b","10 lần swing hết sức không bóng với driver (tốc độ swing tối đa)"],["b","10 bóng driver swing nhẹ"],["b","10 bóng driver swing bình thường"],["b","10 bóng driver swing hết sức"],["p","Hướng dẫn: Làm 30 lần swing không bóng trước, rồi mới đánh 30 cú có bóng đặt trên tee. Dùng cảm giác để nhận ra nhịp khác nhau của từng kiểu swing, rồi tìm cú swing vừa đi xa vừa kiểm soát được. Có thể cú swing bình thường của bạn quá nhanh hoặc quá chậm; bài này giúp nhận ra điều đó và có thể cải thiện độ chính xác hoặc khoảng cách."]]},{"a":"gir","h":"Green (GIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 lần swing toàn phần không bóng với wedge thứ nhất"],["b","10 lần swing nửa vòng không bóng với wedge thứ nhất"],["b","10 lần swing 3/4 không bóng với wedge thứ nhất"],["b","10 bóng swing nửa vòng vào mục tiêu bằng wedge thứ nhất"],["b","10 bóng swing 3/4 vào mục tiêu bằng wedge thứ nhất"],["b","10 bóng swing toàn phần vào mục tiêu bằng wedge thứ nhất"],["p","Hướng dẫn: Tập nhiều độ dài swing với cùng một wedge. Kỹ năng này rất hữu ích cho cú dưới 100 yard, khi phải chỉnh độ dài swing theo khoảng cách tới green. Giữ nhịp swing đều, để độ dài backswing quyết định khoảng cách chứ không phải nhịp. Về lý thuyết, giữ nguyên nhịp và đổi độ dài backswing thì bóng sẽ đi các khoảng cách khác nhau. Hãy tìm ra mỗi độ dài backswing đưa bóng đi xa khoảng bao nhiêu để dùng khi ra sân."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Tập lên dốc và xuống dốc"],["s","Chip 10 bóng tới các lỗ ngẫu nhiên khác nhau. Có thể phải chip nhiều bóng vào cùng một lỗ, tuỳ green tập có bao nhiêu lỗ."],["s","Putt lần lượt cả 10 bóng, cố vào hết. Ghi số bóng putt vào để hoàn thành up & down."],["s","Lặp lại 5 lần, tổng 50 lượt, xem được bao nhiêu up & down thành công trên 50."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách"],["o","Cải thiện khả năng và sự tự tin chip vào lỗ"],["o","Cải thiện cú bump & run"],["o","Cải thiện cú flop"],["p","Bài tập hôm nay:"],["h","1. Chip khối lượng lớn, dừng trong 3 ft quanh nhiều lỗ"],["s","Chip 20/25 bóng dừng trong 3 feet ở lỗ trung bình"],["s","Chip 20/25 bóng dừng trong 3 feet ở lỗ xa"],["s","Chip 22/25 bóng dừng trong 3 feet ở lỗ gần"],["h","2. Chip vào lỗ"],["s","3 cú chip vào lỗ, cùng một lỗ, từ cùng một vị trí trong rough"],["h","3. Bump & run"],["s","40/50 cú bump & run dừng trong 3 feet ở lỗ xa"],["s","20/25 cú bump & run dừng trong 3 feet ở lỗ trung bình"],["h","4. Cú flop"],["s","10/25 cú flop dừng trong 5 feet ở lỗ xa"],["s","15/25 cú flop dừng trong 5 feet ở lỗ trung bình"],["p","Hướng dẫn: Chọn vị trí trong rough cho từng bài. Có thể đứng sát mép green hoặc lùi xa vào rough tuỳ độ khó muốn tập. Bài chip vào lỗ: nếu đã cố một lúc khá lâu mà chưa được 3 cú thì chuyển bài. Với bump & run và flop phải đạt đủ chỉ tiêu mới chuyển bài. Đừng tự lừa mình."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["s","Putt vào 25 bóng bẻ trái từ 7 feet"],["s","Putt vào 25 bóng bẻ phải từ 7 feet"],["h","3. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 50 feet"],["h","4. Putt áp lực: bài vòng tròn (1 vòng)"],["s","Putt vào liên tiếp cả 5 bóng quanh vòng tròn từ 5 feet"],["s","Nếu còn thời gian, làm theo thứ tự ngược lại"],["p","Hướng dẫn: Cố hết sức. Sau 8 tuần liền mỗi ngày putt vào 100 bóng từ 3 feet, cú putt 3 feet của bạn sẽ rất chắc. Khả năng putt nhiều đường bẻ từ nhiều khoảng cách đang tốt lên, putt xa đến giờ phải thành phản xạ. 4 tuần cuối sẽ tập trung vào tâm lý và putt theo tình huống, nên hãy tận hưởng tuần cuối tập khối lượng lớn này."]]}]},{"w":9,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","14 bóng vào mục tiêu bằng driver. Ghi số lần vào fairway, trượt trái và trượt phải. So với tuần 2."],["b","Đánh 2 bóng bằng gậy sắt 4 vào vùng fairway để nghỉ driver một chút"],["b","Đánh 14 bóng vào mục tiêu bằng driver. Ghi số lần vào fairway, trượt trái và trượt phải. So với tuần 2."],["p","Hướng dẫn: Nhớ bài này ở tuần 2 không? Giờ tập lại cả tuần và so kết quả với mấy tuần trước. Bạn phải vào fairway nhiều hơn trước."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","Hôm nay đánh mỗi gậy 10 cú với 3 gậy sắt khác nhau, kết hợp nhiều kiểu cú (draw, fade, thẳng, swing nửa vòng, 3/4, toàn phần)"],["b","Ngày tập 2: chọn 3 gậy sắt mới"],["b","Ngày tập 3: chọn 3 gậy sắt mới, có thể dùng wedge"]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down có chủ đích"],["s","50 cú chip (5 bộ 10) vào vòng tròn 3 foot làm bằng mác bóng trên green tập"],["s","50 cú putt (5 bộ 10) từ chỗ bóng chip dừng tới một lỗ thật gần đó"],["s","Xem hướng dẫn cho mục 1 và 2"],["p","Hướng dẫn: Hôm nay làm một bài khác lạ, có vẻ kỳ cục nhưng giúp bạn quen với những tình huống trớ trêu. Chọn một lỗ trên green tập bạn hay chip tới. Chọn một điểm cách lỗ 15 feet, cắm tee đánh dấu, rồi dựng vòng tròn 3 foot quanh tee như thể đó là lỗ cần chip tới. Chip một bộ 10 bóng vào cái lỗ tự tạo này. Sau đó putt lần lượt từng bóng vào lỗ thật cách tee 15 feet. Nếu chip cả 10 bóng sát tee thì bạn sẽ có những cú up & down rất dài. Những bóng chip hỏng, không gần tee, vẫn tạo ra những cú putt thú vị có ích. Một số bóng chip tệ có thể đã gần lỗ thật, nhưng đừng cố ý chip vào lỗ thật. Hãy chip về tee để tạo ra những cú putt cứu par dài, có kinh nghiệm ở khoảng xa hơn 3–10 feet quen thuộc mấy tuần qua."]]},{"a":"chip","h":"Chip","m":60,"it":[["p","Mục tiêu hôm nay:"],["o","Bản lĩnh quanh green"],["o","Kiểm soát khoảng cách"],["p","Bài tập hôm nay:"],["h","1. Bản lĩnh"],["s","Chip liên tiếp 10 bóng dừng trong 3 feet ở lỗ cách 20–30 ft"],["s","Chip liên tiếp 10 bóng dừng trong 3 feet ở lỗ xa (40 ft) bằng bump & run"],["s","Chip liên tiếp 5 bóng dừng trong 3 feet ở lỗ cách 20–30 ft bằng flop"],["s","Chip liên tiếp 5 bóng dừng trong 3 feet ở lỗ gần bằng chip thường"],["h","2. Chip từ cách green 25 feet"],["s","50 cú chip (5 bộ 10) tới lỗ giữa green tập"],["s","25 cú flop tới lỗ gần, khó trên green tập"],["h","3. Chip từ cách green 15 feet"],["s","25 cú chip thường tới lỗ xa"],["s","25 cú bump & run tới lỗ xa"],["p","Hướng dẫn: Đo 15 feet và 25 feet vào rough bằng bước dài (mỗi bước khoảng 3 feet). Bài này giúp đưa bóng gần lỗ ngay cả khi trượt green nặng, cách green 25 feet và cách lỗ hơn 25 feet."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực"],["o","Tự tin khi putt xa"],["o","Cải thiện putt từ 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào liên tiếp 50 bóng từ 3 feet"],["h","2. Putt từ fringe"],["s","40/50 cú putt từ fringe tới lỗ xa dừng trong 3 feet"],["h","3. Putt xa (lag)"],["s","Lag liên tiếp 10 bóng dừng trong 3 feet từ 20 feet"],["s","Lag liên tiếp 10 bóng dừng trong 3 feet từ 30 feet"],["s","Lag liên tiếp 10 bóng dừng trong 3 feet từ 40 feet"],["h","4. Putt đường bẻ"],["s","Putt vào liên tiếp 10 bóng bẻ trái từ 4 feet"],["s","Putt vào liên tiếp 10 bóng bẻ phải từ 4 feet"],["s","Putt vào 100 bóng từ 6 feet ở mọi vị trí quanh lỗ để có đủ đường bẻ và góc lỗ"]]}]},{"w":10,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","5 cú quỹ đạo cao bằng driver"],["b","5 cú quỹ đạo trung bình bằng driver"],["b","5 cú quỹ đạo thấp bằng driver"],["b","5 cú quỹ đạo cao bằng gậy sắt 4"],["b","5 cú quỹ đạo trung bình bằng gậy sắt 4"],["b","5 cú quỹ đạo thấp bằng gậy sắt 4"],["p","Hướng dẫn: Tập quỹ đạo cao, trung bình và thấp với driver và gậy sắt 4. Dịch vị trí bóng trong thế đứng để hỗ trợ: thường đưa bóng lên trước giúp bay cao, lùi bóng ra sau giúp bay thấp. Nếu chưa chắc, xem video hướng dẫn trước khi tập."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 cú quỹ đạo cao bằng gậy sắt 7"],["b","5 cú quỹ đạo cao bằng gậy sắt 8"],["b","5 cú quỹ đạo cao bằng gậy sắt 9"],["b","5 cú quỹ đạo thấp bằng gậy sắt 7"],["b","5 cú quỹ đạo thấp bằng gậy sắt 8"],["b","5 cú quỹ đạo thấp bằng gậy sắt 9"],["p","Hướng dẫn: Ngày 2 và ngày 3 dùng gậy khác, tiếp tục tập cú cao và thấp. Dịch bóng lên trước hoặc ra sau trong thế đứng để hỗ trợ."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Khối lượng lớn từ rough quanh green"],["s","Hoàn thành 50 up & down tới các lỗ tự chọn ngẫu nhiên trên green tập."],["p","Hướng dẫn: Dùng bộ 5 bóng cho nhanh, vì dùng một bóng sẽ rất lâu. (Ví dụ: chip 5 bóng, putt cả 5, vào 3 thì còn 47 up & down. Chip tiếp 5 bóng, putt, trừ số bóng vào khỏi 47.)"]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách"],["o","Tập trung đưa bóng dừng trong 3 feet để putt dễ"],["p","Bài tập hôm nay:"],["h","1. Kiểm soát khoảng cách"],["s","Chip 50 bóng (5 bộ 10) tới lỗ xa. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ trung bình. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["s","Chip 50 bóng (5 bộ 10) tới lỗ gần. Ghi số bóng dừng trong 3 feet trên 50 và tính tỉ lệ phần trăm."],["p","Hướng dẫn: Cuối tuần so kết quả và tỉ lệ của cả 3 ngày tập, và so với tuần 3 để xem mình tiến bộ thế nào."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào liên tiếp 75 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 40 bóng bẻ trái từ 4 feet"],["s","Putt vào 40 bóng bẻ phải từ 4 feet"],["s","Putt vào 40 bóng bẻ trái từ 5 feet"],["s","Putt vào 40 bóng bẻ phải từ 5 feet"],["s","Putt vào 40 bóng bẻ trái từ 6 feet"],["s","Putt vào 40 bóng bẻ phải từ 6 feet"],["s","Putt vào 60 bóng từ 10 feet. Tự chọn kết hợp các đường bẻ quanh lỗ."],["h","3. Putt xa (lag)"],["s","25 cú lag từ 40 feet. Ghi số bóng dừng trong 3 feet."],["s","25 cú lag từ 25 feet. Ghi số bóng dừng trong 3 feet."],["p","Hướng dẫn: Mục tiêu bài lag là 80%. Chưa đạt thì thử lại ở ngày 2 và ngày 3, nhưng đã đến tuần 10 tập lag thì cả 3 ngày đều phải làm được."]]}]},{"w":11,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","5 cú quỹ đạo cao bằng driver"],["b","5 cú draw bằng driver"],["b","5 cú quỹ đạo thấp bằng driver"],["b","5 cú fade bằng driver"],["b","5 cú quỹ đạo trung bình bằng driver"],["b","5 cú drive thẳng bình thường"],["p","Hướng dẫn: Tập quỹ đạo và hướng bóng. Mỗi kiểu chỉ đánh 5 lần nên hãy tập trung, cố đạt 4/5. Ghi số cú thành công vào phiếu."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["h","1. Các kiểu cú"],["s","Đánh 10 cú draw bằng nhiều gậy sắt khác nhau"],["s","Đánh 10 cú fade bằng nhiều gậy sắt khác nhau"],["s","Đánh 5 cú bay cao bằng nhiều gậy sắt khác nhau"],["s","Đánh 5 cú bay thấp bằng nhiều gậy sắt khác nhau"],["p","Hướng dẫn: Xen thêm wedge cho cú cao và thấp, vì quanh green sẽ gặp những cú cần đánh thấp 50 yard (punch) hoặc đánh cao 20 yard."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Khối lượng lớn từ rough quanh green"],["s","Hoàn thành 10 up & down tới lỗ gần"],["s","Hoàn thành 10 up & down tới lỗ trung bình"],["s","Hoàn thành 30 up & down tới lỗ xa"],["p","Hướng dẫn: Dùng một bóng để tập trung tối đa."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Bài tập hôm nay:"],["h","1. Kiểm soát khoảng cách"],["s","Chip 50 bóng (5 bộ 10) tới lỗ xa."],["h","2. Cú flop"],["s","Chip 10 bóng tới lỗ gần"],["s","Chip 10 bóng tới lỗ giữa"],["s","Chip 10 bóng tới lỗ xa"],["h","3. Bump & run"],["s","Chip 10 bóng tới lỗ gần"],["s","Chip 10 bóng tới lỗ giữa"],["s","Chip 10 bóng tới lỗ rất xa"],["h","4. Chip xuống dốc"],["s","Chip 10/10 bóng dừng trong 3 feet ở lỗ xuống dốc"],["s","Ưu tiên lỗ trung bình hoặc lỗ xa; nếu không có thì dùng lỗ gần"],["p","Hướng dẫn: Cuối tuần so kết quả và tỉ lệ của cả 3 ngày tập, và so với tuần 3 để xem mình tiến bộ thế nào."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Putt đường bẻ từ nhiều khoảng cách"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào liên tiếp 75 bóng từ 3 feet"],["h","2. Putt đường bẻ"],["s","Putt vào 40 bóng bẻ trái từ 4 feet"],["s","Putt vào 40 bóng bẻ phải từ 4 feet"],["s","Putt vào 40 bóng bẻ trái từ 5 feet"],["s","Putt vào 40 bóng bẻ phải từ 5 feet"],["s","Putt vào 40 bóng bẻ trái từ 6 feet"],["s","Putt vào 40 bóng bẻ phải từ 6 feet"],["s","Putt vào 60 bóng từ 10 feet. Tự chọn kết hợp các đường bẻ quanh lỗ."],["h","3. Putt xa (lag)"],["s","25 cú lag từ 40 feet. Ghi số bóng dừng trong 3 feet."],["s","25 cú lag từ 25 feet. Ghi số bóng dừng trong 3 feet."],["p","Hướng dẫn: Mục tiêu bài lag là 80%. Chưa đạt thì thử lại ở ngày 2 và ngày 3, nhưng đã đến tuần 10 tập lag thì cả 3 ngày đều phải làm được."]]}]},{"w":12,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","Đánh 7 cú drive draw. Ghi số lần vào fairway."],["b","Đánh 7 cú drive fade. Ghi số lần vào fairway."],["b","Đánh 7 cú gỗ fairway draw. Ghi số lần vào fairway."],["b","Đánh 7 cú gỗ fairway fade. Ghi số lần vào fairway."],["b","Đánh 1 cú bay cao bằng gỗ fairway"],["b","Đánh 1 cú bay thấp bằng gỗ fairway"],["p","Hướng dẫn: Chia bóng thành từng nhóm 7, dùng các kiểu cú khác nhau để đánh vào vùng fairway rộng 30 yard tự hình dung. Chọn mục tiêu, hình dung 15 yard mỗi bên để mô phỏng fairway."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 cú tới mục tiêu 100 yard"],["b","5 cú tới mục tiêu 150 yard"],["b","5 cú tới mục tiêu 200 yard"],["b","5 cú tới mục tiêu 125 yard"],["b","5 cú tới mục tiêu 175 yard"],["b","5 cú tới mục tiêu 75 yard"],["p","Hướng dẫn: Dùng nhiều gậy và độ dài swing khác nhau cho từng mục tiêu. Thử cả quỹ đạo khác nhau và hướng bóng (draw, fade)."]]},{"a":"scr","h":"Up & down (cứu par)","m":30,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Khối lượng lớn từ rough quanh green"],["s","18 lượt up & down. Ghi số lượt thành công trên 18 và tính tỉ lệ up & down của vòng 1."],["s","Nghỉ ngắn để tính kết quả vòng 1, rồi làm lại cho vòng 2 và vòng 3."],["p","Hướng dẫn: Dùng một bóng, mỗi lần một lượt up & down. Sau 18 lượt nghỉ để cộng điểm, rồi làm thêm 2 vòng, xem vòng nào tốt nhất. Cố đạt từ 80% trở lên (15 hoặc 16 trên 18)."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách"],["o","Tập trung đưa bóng dừng trong 3 feet để putt dễ"],["p","Bài tập hôm nay:"],["h","1. Kiểm soát khoảng cách từ rough quanh green (cách green khoảng 5 feet)"],["s","Chip 45/50 bóng dừng trong 3 feet ở lỗ xa"],["s","Chip 48/50 bóng dừng trong 3 feet ở lỗ giữa"],["s","Chip 50/50 bóng dừng trong 3 feet ở lỗ gần"],["p","Hướng dẫn: Tuần 12 là sự hoàn hảo. Chip liên tiếp 50 bóng dừng trong 3 feet ở lỗ gần (cách 10 ft trở xuống). Chúc may mắn."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực"],["o","Cải thiện theo khoảng cách tới lỗ"],["o","Putt xa dưới áp lực và cải thiện putt xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào liên tiếp 75 bóng từ 3 feet"],["h","2. Putt theo khoảng cách"],["s","Putt vào 20 bóng từ 4 feet"],["s","Putt vào 20 bóng từ 5 feet"],["s","Putt vào 20 bóng từ 6 feet"],["s","Putt vào 20 bóng từ 7 feet"],["s","Putt vào 20 bóng từ 8 feet"],["s","Putt vào 25 bóng từ 10 feet"],["s","Putt vào 25 bóng từ 12 feet"],["s","Putt vào 10 bóng từ 15 feet"],["h","3. Putt xa (lag)"],["s","Liên tiếp 10 cú putt dừng trong 3 feet từ 25 feet"],["s","Liên tiếp 10 cú putt dừng trong 3 feet từ 35 feet"],["s","Liên tiếp 10 cú putt dừng trong 3 feet từ 50 feet"]]}]}],"b70":[{"w":1,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","10 cú driver vào vùng rộng 30 yard trên sân tập, mô phỏng fairway rộng 30 yard."],["b","10 cú gỗ fairway vào vùng rộng 30 yard trên sân tập"],["b","10 cú driver vào vùng rộng 30 yard trên sân tập"],["p","Hướng dẫn: Chọn mục tiêu để căn hướng, hình dung 15 yard mỗi bên tạo vùng rộng 30 yard. Đếm số cú nằm trong vùng của từng gậy, chỉ tiêu 8/10 để qua mỗi bài trong 3 bài. Ghi kết quả từng gậy trên 10 và tỉ lệ vào phiếu. Cố qua cả 3 bài trong cùng một ngày ít nhất một lần trong tuần."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 cú gậy sắt 7 vào mục tiêu"],["b","5 cú gậy sắt 5 vào mục tiêu"],["b","5 cú gậy sắt 9 vào mục tiêu"],["b","5 cú gậy sắt 6 vào mục tiêu"],["b","5 cú gậy sắt 4 vào mục tiêu"],["b","5 cú gậy sắt 8 vào mục tiêu"],["p","Hướng dẫn: Với mỗi gậy trong 6 gậy, chọn mục tiêu gần đúng khoảng cách đánh của gậy đó, dùng que căn hướng đặt dưới đất để nhắm. Sau mỗi 5 cú của một gậy, ghi vào phiếu số cú sẽ vào green trên 5, tính cả khoảng cách và độ chính xác. Đạt 4/5 là qua gậy đó. Cố qua cả 6 gậy trong cùng một ngày."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["b","Hoàn thành 25 up & down từ fringe tới lỗ cách khoảng 10 feet."],["b","Hoàn thành 25 up & down từ fringe tới lỗ cách khoảng 25 feet."],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Đủ 25 up & down thì đánh dấu hoàn thành trên phiếu và chuyển bài."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe"],["o","Cải thiện kiểm soát khoảng cách từ rough"],["p","Bài tập hôm nay:"],["b","50 cú chip (5 bộ 10 bóng) từ fringe tới lỗ cách khoảng 35 feet"],["b","50 cú chip (5 bộ 10 bóng) từ rough tới lỗ cách khoảng 10 feet"],["b","50 cú chip (5 bộ 10 bóng) từ rough tới lỗ cách khoảng 25 feet"],["b","50 cú chip (5 bộ 10 bóng) từ rough tới lỗ cách khoảng 40 feet"],["p","Hướng dẫn: Ra green putt tập ở sân có cho phép chip. Làm bài từ fringe ở trên và 3 bài từ rough. Tập trung từng cú, cố đưa bóng dừng trong 3 feet quanh lỗ. Nếu sân không cho chip lên green putt, hãy tận dụng green chip/pitch ở khu tập khác. Green chip thường lăn không đều, chỉ giúp tập điểm rơi, nên tốt nhất là tìm được green putt cho phép chip vào lỗ."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Vì bạn thuộc nhóm handicap dưới 10, chúng tôi coi như đường putt của bạn đã vững nên không cần dành nhiều thời gian cho bài nền tảng về đường gậy. Tuần đầu sẽ tập khối lượng lớn putt gần để xây nền vững cho cú putt dưới 5 feet và tăng tự tin khi gặp cú putt ngắn trên sân."],["p","Mục tiêu hôm nay:"],["o","Đường gậy nền tảng: chuyển động thẳng theo thanh chắn hoặc cổng để thấy lỗi"],["o","Putt gần: cải thiện ở 2 feet, 3 feet và 5 feet"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Bài cổng: đặt hai gậy hướng vào lỗ để dẫn đường putt. Có thể dùng hai tee làm cổng, nhưng dùng gậy giúp mắt nhìn đường tới lỗ tốt hơn."],["s","25 lần đánh không bóng"],["s","Putt vào 25 bóng từ 3 feet"],["h","2. Khởi động: putt vào ở cự ly gần"],["s","Putt vào 100 bóng từ 2 feet, đường thẳng (mặt phẳng)"],["s","Putt vào 100 bóng từ 3 feet, đường thẳng (mặt phẳng)"],["s","Putt vào 50 bóng từ 5 feet, đường thẳng (mặt phẳng)"],["h","3. Putt xa (lag): ghi số bóng dừng trong 3 feet quanh lỗ"],["s","100 cú putt (10 bộ 10 bóng) từ cách lỗ 20 feet."],["s","100 cú putt (10 bộ 10 bóng) từ cách lỗ 30 feet"],["h","4. Putt thêm (điểm cộng): thêm 400 bóng putt vào"],["s","Putt vào 100 bóng bẻ trái từ 5 feet"],["s","Putt vào 100 bóng bẻ phải từ 5 feet"],["s","Putt vào 50 bóng một tay trái từ 3 feet"],["s","Putt vào 50 bóng một tay phải từ 3 feet"],["p","Hướng dẫn: Tìm một đường putt phẳng, cắm tee ở 2 feet và 3 feet. Xong 3 bài putt gần thì chuyển sang bài putt xa. Putt xa (lag) là cố đưa bóng dừng trong 3 feet quanh lỗ. Ở bài putt xa, đếm số bóng dừng trong 3 feet và ghi vào phiếu. Dùng chiều dài putter để đo, vì putter dài khoảng 3 feet."]]}]},{"w":2,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR:"],["b","5 cú driver. Ghi số lần vào fairway trên 5."],["b","5 cú gỗ. Ghi số lần vào fairway trên 5."],["b","5 cú driver. Ghi số lần vào fairway trên 5."],["b","5 cú gỗ. Ghi số lần vào fairway trên 5."],["b","5 cú driver. Ghi số lần vào fairway trên 5."],["b","5 cú gỗ. Ghi số lần vào fairway trên 5."],["p","Hướng dẫn: Chọn mục tiêu để căn hướng, hình dung 15 yard mỗi bên tạo vùng rộng 30 yard. Đếm số cú trong vùng của mỗi bài trên 5 và ghi vào phiếu. Đạt từ 4/5 là qua, dưới 4 là chưa qua. Cố qua cả 6 bài trong cùng một ngày ít nhất một lần trong 3 ngày tập của tuần."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","5 cú gậy sắt 6 vào mục tiêu"],["b","5 cú gậy sắt 9 vào mục tiêu"],["b","5 cú gậy sắt 4 vào mục tiêu"],["b","5 cú gậy sắt 7 vào mục tiêu"],["b","5 cú gậy sắt 8 vào mục tiêu"],["b","5 cú gậy sắt 5 vào mục tiêu"],["p","Hướng dẫn: Với mỗi gậy trong 6 gậy, chọn mục tiêu gần đúng khoảng cách đánh của gậy đó, dùng que căn hướng đặt dưới đất để nhắm. Sau mỗi 5 cú của một gậy, ghi vào phiếu số cú sẽ vào green trên 5, tính cả khoảng cách và độ chính xác. Đạt 4/5 là qua gậy đó. Cố qua cả 6 gậy trong cùng một ngày ít nhất một lần trong 3 ngày tập của tuần."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down từ rough bằng wedge quen dùng"],["s","10 up & down liên tiếp tới lỗ gần (cách khoảng 10 ft)"],["s","10 up & down liên tiếp tới lỗ trung bình (cách khoảng 25 ft)"],["s","10 up & down liên tiếp tới lỗ xa (cách khoảng 40 ft)"],["p","Hướng dẫn: Chọn một điểm trong rough sát green tập. Hoàn thành 10 up & down liên tiếp cho mỗi lỗ trong 3 lỗ, putt trượt thì đếm lại từ 0. Lỗ xa rất khó đạt 10 lượt liên tiếp; nếu đã cố khá lâu mà chưa được thì chuyển bài và thử lại ở buổi tập sau."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách từ rough"],["o","Cải thiện kiểm soát khoảng cách từ fringe"],["o","Cải thiện cú bump & run và flop"],["p","Bài tập hôm nay:"],["h","1. Chip từ rough dừng trong 3 feet quanh lỗ"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ gần"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ trung bình"],["s","Đạt 25 cú chip dừng trong 3 feet ở lỗ xa"],["h","2. Bump & run vào vùng tự tạo (vòng tròn đường kính 6 ft) cách 35 feet"],["s","25 cú bump & run bằng wedge 54 độ"],["s","25 cú bump & run bằng gậy 48 hoặc 50 độ (pitching wedge)"],["h","3. Chip áp lực vào vùng tự tạo (vòng tròn đường kính 6 ft) cách 20 feet"],["s","Chip liên tiếp 15 bóng vào trong vòng tròn bằng gậy chip quen dùng"],["h","4. Chip từ fringe"],["s","30 cú chip (3 bộ 10) từ fringe tới lỗ gần, cố chip vào lỗ. Ghi số bóng chip vào và cố vượt ở ngày tập 2 và 3."],["h","5. Cú flop"],["s","30 cú flop (3 bộ 10) tới mục tiêu tự chọn"],["p","Hướng dẫn: Ra green tập ở sân có cho phép chip. Với bài tự tạo vùng đích, dùng tee hoặc mác bóng làm lỗ giả ở đúng khoảng cách bài yêu cầu. Từ điểm giữa (lỗ giả) đo 3 feet ra nhiều phía và đặt mác, tạo vòng tròn đường kính 6 foot."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt gần: cải thiện từ 3 feet đến 6 feet"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ (điểm cộng)"],["o","Putt áp lực (điểm cộng)"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Cải thiện putt ngắn"],["s","Putt vào 50 bóng từ 4 feet"],["s","Putt vào 50 bóng từ 5 feet"],["s","Putt vào 50 bóng từ 6 feet"],["h","3. Putt xa (lag)"],["s","Đạt 40/50 cú putt dừng trong 3 feet từ 20 feet"],["s","Đạt 80/100 cú putt dừng trong 3 feet từ 30 feet"],["s","Đạt 80/100 cú putt dừng trong 3 feet từ 40 feet"],["h","4. Điểm cộng"],["s","100 cú putt bẻ trái từ 5 feet"],["s","100 cú putt bẻ phải từ 5 feet"],["s","Putt vào liên tiếp 20 bóng từ 3 feet"],["s","Putt vào liên tiếp 10 bóng từ 4 feet"],["s","Putt vào liên tiếp 5 bóng từ 6 feet"],["p","Hướng dẫn: Bài 3 (putt xa) phải đạt đủ số bóng dừng trong 3 feet mới qua. Không đạt 40/50 hoặc 80/100 thì làm lại. Để tiết kiệm thời gian, hễ có quá 10 (hoặc quá 20) bóng nằm ngoài 3 foot là làm lại ngay."]]}]},{"w":3,"d":0,"s":[{"a":"fir","h":"Fairway (FIR) và green (GIR)","m":60.0,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 7, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 8, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 5, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gỗ, wedge (40–80 yard)"],["b","Lặp lại 4 chuỗi trên theo thứ tự thêm 4 lần, tổng 5 vòng (mỗi vòng 12 cú), tổng cộng 60 cú"],["p","Hướng dẫn: Hôm nay mô phỏng tình huống trên sân. Chọn mục tiêu cho driver như thường lệ, đặt vùng rộng 20–30 yard tuỳ độ khó muốn tập. Đánh một cú driver, lùi lại lấy gậy sắt, căn hướng tới green mục tiêu của gậy đó và đánh cú thứ hai. Sau đó lấy wedge (pitching, gap, sand, 58 độ…) đánh tới mục tiêu 40–80 yard để tập wedge dưới 100 yard. Lặp chuỗi 3 cú này 5 lần cho mỗi mục trong 4 mục trên, tổng 60 cú."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","2. Up & down từ rough quanh green bằng wedge quen dùng"],["s","20 up & down liên tiếp tới lỗ gần (cách khoảng 10 ft)"],["s","10 up & down liên tiếp tới lỗ trung bình (cách khoảng 25 ft)"],["s","10 up & down liên tiếp tới lỗ xa (cách khoảng 40 ft)"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe"],["o","Cải thiện kiểm soát khoảng cách từ nhiều vị trí trong rough"],["o","Cải thiện kỹ năng xử lý khi có ít, vừa hoặc nhiều mặt green để bóng lăn"],["p","Bài tập hôm nay:"],["h","1. Chip từ fringe"],["s","50 cú chip từ fringe tới lỗ xa (40 ft trở lên)"],["h","2. Rough quanh green (cách green 5 ft)"],["s","10 cú chip bằng wedge quen dùng tới lỗ trung bình"],["s","10 cú chip bằng pitching wedge tới lỗ trung bình"],["s","10 cú chip bằng gậy sắt 9 tới lỗ trung bình"],["s","20 cú chip bằng wedge quen dùng tới lỗ xa"],["h","3. Rough xa (cách green 15 ft)"],["s","20 cú chip quỹ đạo trung bình tới lỗ trung bình"],["s","20 cú flop tới lỗ gần (ít mặt green từ rough tới lỗ)"],["s","10 cú chip quỹ đạo trung bình tới lỗ xa (nhiều mặt green để bóng lăn)"],["h","4. Rough xa (cách green 25 ft)"],["s","10 cú flop tới lỗ gần"],["s","10 cú flop tới lỗ trung bình"],["s","10 cú flop tới lỗ xa"],["s","Đạt 10 cú chip dừng trong 3 feet quanh lỗ, dùng quỹ đạo trung bình đến cao, tới lỗ giữa green (khoảng cách trung bình từ mép green tới lỗ)"],["p","Hướng dẫn: Đứng ở mép green sẽ có lỗ gần mình, lỗ ở giữa green tập và lỗ xa ở phía bên kia. Gọi đó là lỗ gần, trung bình và xa. Làm các bài trên với nhiều gậy và quỹ đạo khác nhau tới các lỗ. Bạn cũng lùi dần vào rough, từ 5 ft lên 15 ft rồi 25 ft. Bài này giúp chip tốt hơn khi trượt green 5–8 yard chứ không chỉ vài yard. Hy vọng bạn sẵn sàng cho thử thách."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Putt bẻ trái và bẻ phải từ nhiều khoảng cách"],["o","Putt áp lực"],["o","Putt xa (lag)"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Cải thiện putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 5 feet"],["s","Putt vào 25 bóng bẻ phải từ 5 feet"],["h","3. Putt áp lực: bài vòng tròn"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 4 feet"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 5 feet"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 6 feet"],["h","4. Putt xa (lag)"],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 25 feet. Làm lại nếu quá 5 bóng không dừng trong 3 feet."],["s","Lag 40/50 bóng từ 35 feet. Làm lại nếu quá 10 bóng không dừng trong 3 feet."],["p","Hướng dẫn: Bài 3 (putt vòng tròn): tạo vòng tròn bán kính 3 foot quanh lỗ với 5 vị trí cách đều nhau. Đặt một bóng ở mỗi tee, putt lần lượt từ tee này sang tee kia, phải vào liên tiếp. Trượt một bóng thì làm lại. Vào liên tiếp đủ 5 bóng quanh vòng thì lùi các tee ra thêm 1 foot."]]}]},{"w":4,"d":0,"s":[{"a":"fir","h":"Fairway (FIR) và green (GIR)","m":60.0,"it":[["p","Bài tập tăng tỉ lệ FIR: Mô phỏng trên sân, phần 2"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 6, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 4, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gậy sắt 9, wedge (40–80 yard)"],["b","Đánh chuỗi 3 cú: driver, gỗ, wedge (40–80 yard)"],["b","Lặp lại 4 chuỗi trên theo thứ tự thêm 4 lần, tổng 5 vòng (mỗi vòng 12 cú), tổng cộng 60 cú"],["p","Hướng dẫn: Hôm nay mô phỏng tình huống trên sân. Chọn mục tiêu cho driver như thường lệ, đặt vùng rộng 20–30 yard tuỳ độ khó muốn tập. Đánh một cú driver, lùi lại lấy gậy sắt, căn hướng tới green mục tiêu của gậy đó và đánh cú thứ hai. Sau đó lấy wedge (pitching, gap, sand, 58 độ…) đánh tới mục tiêu 40–80 yard để tập wedge dưới 100 yard. Làm chuỗi 3 cú này 5 lần cho mỗi mục trong 4 mục trên, tổng 60 cú."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","3. Up & down từ rough quanh green bằng wedge quen dùng"],["s","10 up & down liên tiếp tới lỗ trung bình (cách khoảng 10 ft)"],["s","10 up & down liên tiếp tới lỗ gần (cách khoảng 25 ft)"],["s","10 up & down liên tiếp tới lỗ xa (cách khoảng 40 ft)"],["s","Tổng 20 up & down tới các lỗ tự chọn. Thay đổi thế bóng và khoảng cách tới green."],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Phải đạt 10 up & down liên tiếp, nếu không thì mỗi lần trượt đếm lại từ 0. Sau đó hoàn thành 20 up & down tự chọn, không cần liên tiếp."]]},{"a":"chip","h":"Chip","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách từ nhiều vị trí trong rough"],["o","Cải thiện cú bump & run"],["o","Cải thiện cú flop"],["p","Bài tập hôm nay:"],["h","1. Chip từ xa green"],["s","50 cú chip dừng trong 3 feet, từ cách green 10 ft tới lỗ trung bình"],["s","50 cú chip dừng trong 3 feet, từ cách green 15 ft tới lỗ xa"],["s","50 cú chip dừng trong 3 feet, từ cách green 20 ft tới lỗ xa"],["h","2. Bump & run"],["s","25 cú chip dừng trong 3 feet tới lỗ xa từ nhiều khoảng cách ngoài green. Tự chọn khoảng cách"],["h","3. Cú flop"],["s","25 cú chip dừng trong 3 feet, từ cách green 30 ft tới lỗ trung bình"],["p","Hướng dẫn: Hôm nay phải thật tập trung vì cần 200 cú chip dừng trong 3 feet mới xong phần chip. Nếu tỉ lệ thành công 66% thì chỉ cần khoảng 300 lượt để đạt 200. Chúc may mắn."]]},{"a":"putt","h":"Putt","m":75,"it":[["p","Mục tiêu hôm nay:"],["o","Putt xa (lag)"],["o","Putt áp lực"],["o","Cải thiện putt trong 10 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt xa (lag)"],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Làm lại nếu quá 5 bóng không dừng trong 3 feet."],["s","Lag 45/50 bóng từ 40 feet. Làm lại nếu quá 5 bóng không dừng trong 3 feet."],["h","3. Bài thẳng hàng: cắm tee ở 3 ft, 6 ft, 9 ft và 12 ft trên một đường thẳng"],["s","Putt vào liên tiếp cả 4 bóng, bắt đầu từ 3 feet"],["s","Putt vào liên tiếp cả 4 bóng theo thứ tự ngược, bắt đầu từ 12 feet"],["h","4. Cải thiện theo khoảng cách"],["s","Putt vào 50 bóng bẻ trái từ 6 feet"],["s","Putt vào 50 bóng bẻ phải từ 6 feet"],["s","Putt vào 50 bóng bẻ trái từ 7 feet"],["s","Putt vào 50 bóng bẻ phải từ 7 feet"],["p","Hướng dẫn: Bài 3: đặt một bóng ở mỗi tee trong 4 tee. Putt vào bóng 3 feet rồi lùi ra bóng 6 feet. Phải vào liên tiếp cả 4, nếu không thì làm lại từ bóng 3 feet. Ở thử thách ngược, mỗi lần trượt làm lại từ 12 feet cho tới khi vào liên tiếp cả 4."]]}]},{"w":5,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR: Điều hướng bóng với draw và fade"],["b","10 cú draw bằng driver. Ghi số cú draw thành công, không tính vào fairway."],["b","10 cú thẳng bằng driver. Ghi số lần vào fairway."],["b","10 cú fade bằng driver. Ghi số cú fade thành công, không tính vào fairway."],["p","Hướng dẫn: Đã qua 4 tuần cú cơ bản và tình huống trên sân. Giờ là lúc tập điều hướng bóng để có kỹ năng toàn diện với các gậy. Đánh 10 cú draw và 10 cú fade bằng driver, ghi số bóng cong đúng ý. Chưa cần chính xác vào vùng fairway 30 yard, hôm nay chỉ tập điều hướng, độ chính xác sẽ ghi ở tuần khác. Với 10 cú drive thẳng vẫn ghi số lần vào fairway trên 10 như thường lệ."],["p","Nếu hoàn toàn chưa biết cách đánh draw hay fade, hãy tìm tài liệu trên mạng và xem video hướng dẫn để học."]]},{"a":"gir","h":"Green (GIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 cú draw bằng gậy sắt 7"],["b","10 cú thẳng bằng gậy sắt 7"],["b","10 cú fade bằng gậy sắt 7"],["b","Ngày tập 2: dùng gậy sắt 6 thay cho gậy sắt 7"],["b","Ngày tập 3: dùng gậy sắt 5 thay cho gậy sắt 6"],["p","Hướng dẫn: Ở trên bạn đã tập draw và fade với driver. Giờ làm tương tự với gậy sắt 7, 6 và 5. Ngày tập đầu dùng gậy sắt 7, ngày 2 dùng gậy sắt 6, và kết thúc tuần bằng gậy sắt 5 ở ngày tập 3."],["d","Ghi vào phiếu số cú cong đúng ý trên 10 cho mỗi kiểu cú. Với cú thẳng, ghi số lần vào green theo vùng mục tiêu bình thường. Thời gian: 20 phút"]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Tập lên dốc và xuống dốc từ rough quanh green"],["s","Hoàn thành 20 up & down từ rough quanh green (cách mép green 5 ft) tới lỗ xuống dốc cách khoảng 20–30 ft."],["s","Hoàn thành 20 up & down từ rough quanh green (cách mép green 5 ft) tới lỗ lên dốc cách khoảng 20–30 ft."],["h","2. Tỉ lệ up & down cự ly ngắn"],["s","Hoàn thành 50 up & down từ rough quanh green (cách mép green 5 ft) tới lỗ gần. Ghi tổng số lượt đã thử để đạt 50 lượt thành công."],["p","Hướng dẫn: Có thể dùng một bóng để tập trung tối đa, hoặc bộ 5 bóng cho nhanh. Chip một hoặc năm bóng về phía lỗ rồi putt mỗi bóng một lần vào lỗ để hoàn thành up & down. Với bài 2, ghi tổng số lượt thử để tính tỉ lệ up & down. (Ví dụ: 50/75 = 67%)"]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát cú flop"],["o","Cải thiện kiểm soát khoảng cách"],["o","Cải thiện kiểm soát điểm rơi"],["p","Bài tập hôm nay:"],["h","1. Cú flop"],["s","50 cú chip tới lỗ cách 40 ft. Ghi số bóng dừng trong 3 feet quanh lỗ"],["h","2. Chip áp lực"],["s","Đạt 15/15 bóng dừng trong 3 feet khi chip từ rough quanh green tới lỗ cách 20 ft"],["h","3. Tập điểm rơi"],["s","Chip trúng khăn gấp đặt cách 15 feet đủ 20 lần"],["p","Hướng dẫn: Gấp một chiếc khăn thành mục tiêu nhỏ, đặt trên green tập cách bạn 15 feet. Chip sao cho bóng rơi trúng khăn. Có thể đánh cả từ rough và fringe để quen cả hai thế bóng."]]},{"a":"putt","h":"Putt","m":90,"it":[["p","Mục tiêu hôm nay:"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Cải thiện putt từ fringe"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["o","Putt đường bẻ: cải thiện ở 4 feet và 6 feet"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt áp lực: trò chơi 18 hố (xem hướng dẫn bên dưới)"],["s","6 cú putt từ 4 ft đến 10 ft"],["s","6 cú putt từ 11 ft đến 25 ft"],["s","6 cú putt từ 25 ft đến 50 ft"],["s","Ghi điểm và vượt điểm đó mỗi ngày (ngày tập 2 và 3)"],["h","3. Putt từ fringe"],["s","50 cú putt từ fringe tới lỗ gần"],["s","50 cú putt từ fringe tới lỗ trung bình"],["s","50 cú putt từ fringe tới lỗ xa"],["h","4. Putt xa (lag)"],["s","Lag 50/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","Lag 45/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["h","5. Putt đường bẻ"],["s","Putt vào 25 bóng bẻ trái từ 4 feet"],["s","Putt vào 25 bóng bẻ phải từ 4 feet"],["s","Putt vào 25 bóng bẻ trái từ 6 feet"],["s","Putt vào 25 bóng bẻ phải từ 6 feet"],["p","Hướng dẫn trò chơi 18 hố:"],["d","1. Cắm 6 tee quanh một lỗ, cách lỗ từ 4 ft đến 10 ft"],["d","2. Cắm 6 tee quanh một lỗ, cách lỗ từ 11 ft đến 25 ft"],["d","3. Cắm 6 tee quanh một lỗ, cách lỗ từ 25 ft đến 50 ft"],["d","4. Putt từ mỗi tee, tổng cộng 18 cú"],["d","5. Nhóm gần nhất tính là par khi putt một lần. Hai putt ở nhóm 4–10 ft là bogey."],["d","6. Nhóm trung bình (11–25 ft) và nhóm xa (25–50 ft): một putt là birdie, hai putt là par."],["d","7. Ghi điểm, cố đạt par hoặc tốt hơn. Nếu trượt nhiều ở nhóm gần sẽ bị trên par, vì hai putt là bogey và ba putt là double bogey."],["d","8. Không putt liền 6 bóng cùng một nhóm. Hãy xáo trộn: putt một bóng nhóm gần lấy par, rồi chuyển sang một cú xa lấy birdie, cứ thế cho tới hết 18 vị trí."]]}]},{"w":6,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR: Điều hướng bóng với draw và fade"],["b","10 cú draw bằng driver. Ghi số cú draw thành công, không tính vào fairway."],["b","10 cú thẳng bằng driver. Ghi số lần vào fairway."],["b","10 cú fade bằng driver. Ghi số cú fade thành công, không tính vào fairway."],["p","Hướng dẫn: Đánh 10 cú draw và 10 cú fade bằng driver, ghi số bóng cong đúng hướng. Chưa cần chính xác vào vùng fairway 30 yard, hôm nay chỉ tập điều hướng, độ chính xác sẽ ghi ở tuần khác. Với 10 cú drive thẳng vẫn ghi số lần vào fairway trên 10 như thường lệ."],["p","Nếu hoàn toàn chưa biết cách đánh draw hay fade, hãy tìm tài liệu trên mạng và xem video hướng dẫn để học."]]},{"a":"gir","h":"Green (GIR)","m":30,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","10 cú draw bằng gậy sắt 4"],["b","10 cú thẳng bằng gậy sắt 4"],["b","10 cú fade bằng gậy sắt 4"],["b","Ngày tập 2: dùng gỗ fairway thay cho gậy sắt 4"],["b","Ngày tập 3: dùng gậy sắt 8 thay cho gỗ fairway"],["p","Hướng dẫn: Ở trên bạn đã tập draw và fade với driver. Giờ làm tương tự với gậy sắt 4, gỗ fairway và gậy sắt 8. Ngày tập đầu dùng gậy sắt 4, ngày 2 dùng gỗ fairway, và kết thúc tuần bằng gậy sắt 8 ở ngày tập 3. Ghi vào phiếu số cú cong đúng ý trên 10 cho mỗi kiểu cú. Với cú thẳng, ghi số lần vào green theo vùng mục tiêu bình thường."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down liên tiếp"],["s","Hoàn thành liên tiếp 20 up & down từ rough quanh green (cách mép green 5 ft) tới lỗ cách khoảng 20–30 ft."],["h","2. Tỉ lệ up & down cự ly xa"],["s","Hoàn thành 50 up & down từ rough quanh green (cách mép green 5 ft) tới lỗ xa. Ghi tổng số lượt đã thử để đạt 50 lượt thành công."],["p","Hướng dẫn: Có thể dùng một bóng để tập trung tối đa, hoặc bộ 5 bóng cho nhanh. Chip một hoặc năm bóng về phía lỗ rồi putt mỗi bóng một lần vào lỗ để hoàn thành up & down. Ghi tổng số lượt thử để tính tỉ lệ up & down. (Ví dụ: 50/100 = 50%)"]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kiểm soát khoảng cách, đưa bóng dừng trong 3 feet"],["o","Chip vào lỗ thường xuyên hơn và tin rằng mình làm được"],["p","Bài tập hôm nay:"],["h","1. Tập khối lượng lớn"],["s","100 cú chip tới lỗ cách 10–15 ft. Ghi số bóng dừng trong 3 feet trên 100."],["s","100 cú chip tới lỗ cách 20–30 ft. Ghi số bóng dừng trong 3 feet trên 100."],["h","2. Chip vào lỗ"],["s","Chip vào lỗ gần (cách 10 ft trở xuống) đủ 5 bóng từ rough quanh green."],["p","Hướng dẫn: Nếu chip vào đủ 5 bóng ở lỗ gần mất quá nhiều thời gian thì chuyển bài. Hy vọng bạn làm được khá nhanh."]]},{"a":"putt","h":"Putt","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Putt đường bẻ dưới áp lực"],["o","Putt xuống dốc: tăng tự tin khi bóng nằm phía trên lỗ trong vòng đấu"],["o","Putt một tay: cải thiện đường putt toàn diện và cảm giác khoảng cách"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Cải thiện putt đường bẻ"],["s","Putt vào 70/100 bóng bẻ trái từ 4 feet. Không đạt thì làm lại."],["s","Putt vào 70/100 bóng bẻ phải từ 4 feet. Không đạt thì làm lại."],["h","3. Lag xuống dốc: nếu được, tìm đường putt xuống dốc trên green tập"],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 10 feet. Không đạt thì làm lại."],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 15 feet. Không đạt thì làm lại."],["s","Lag 40/50 bóng dừng trong 3 feet quanh lỗ từ 20 feet. Không đạt thì làm lại."],["h","4. Putt một tay"],["s","Putt vào 25 bóng từ 5 feet bằng tay phải"],["s","Putt vào 25 bóng từ 5 feet bằng tay trái"],["p","Hướng dẫn: Bài 3: nếu green tập không có nhiều dốc thì tập lag bình thường từ khoảng xa hơn."]]}]},{"w":7,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":20,"it":[["p","Bài tập tăng tỉ lệ FIR: Điều hướng bóng chính xác với draw và fade"],["b","Đánh 5 cú draw bằng driver. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú draw bằng gỗ fairway. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú draw bằng gậy sắt 4. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú draw bằng gậy sắt 5. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú fade bằng driver. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú fade bằng gỗ fairway. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú fade bằng gậy sắt 4. Ghi số lần vào fairway trên 5."],["b","Đánh 5 cú fade bằng gậy sắt 5. Ghi số lần vào fairway trên 5."],["p","Hướng dẫn: Đánh 5 cú draw và 5 cú fade với mỗi gậy trong 4 gậy, ghi số bóng cong đúng hướng mà vẫn nằm trong vùng fairway rộng 30 yard. Nhớ chọn mục tiêu và hình dung vùng fairway trước khi bắt đầu. Dùng cùng một mục tiêu cho cả 4 gậy, vì hôm nay gậy sắt cũng đánh vào fairway tưởng tượng chứ không phải green."]]},{"a":"gir","h":"Green (GIR)","m":15,"it":[["p","Bài tập tăng tỉ lệ GIR:"],["b","Đánh 5 cú draw bằng gậy sắt 6. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw bằng gậy sắt 7. Ghi số lần vào green trên 5."],["b","Đánh 5 cú fade bằng gậy sắt 6. Ghi số lần vào green trên 5."],["b","Đánh 5 cú fade bằng gậy sắt 7. Ghi số lần vào green trên 5."],["p","Hướng dẫn: Chọn mục tiêu cho gậy sắt 6 và mục tiêu cho gậy sắt 7 như một green thật. Đánh 5 cú draw và 5 cú fade với mỗi gậy, ghi số cú sẽ vào green trên 5. Thời gian dự kiến: 15 phút"]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Up & down tập trung"],["s","Đạt 9/10 up & down từ rough quanh green tới lỗ cách 30 ft"],["s","Đạt 9/10 up & down từ cách mép green 20 ft tới lỗ giữa green tập"],["s","Đạt 9/10 up & down bằng cú flop tới lỗ xa trên green tập, chip từ cách mép green 10 ft"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Bài nào không đạt 9/10 thì làm lại."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe"],["o","Cải thiện kiểm soát khoảng cách"],["o","Cải thiện cảm giác từ nhiều khoảng cách ngoài mép green"],["o","Cải thiện khả năng đánh từ nhiều thế bóng"],["p","Bài tập hôm nay:"],["h","1. Chip trộn tự chọn"],["s","100 cú chip dừng trong 3 feet tới đủ các lỗ trên green tập"],["p","Hướng dẫn: Thay đổi thế bóng, khoảng cách tới mép green và lỗ chip tới"]]},{"a":"putt","h":"Putt","m":60,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện putt gần: ổn định trong 10 feet"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Tấn công khoảng cách: putt khối lượng lớn"],["s","Putt vào 50 bóng từ 4 feet"],["s","Putt v