green tập"],["s","5/5 up & down từ rough quanh green tới các lỗ khác nhau"],["s","5/5 up & down từ cách mép green 10 ft tới các lỗ khác nhau"],["s","5/5 up & down từ cách mép green 15 ft tới các lỗ khác nhau"],["s","5/5 up & down từ cách mép green 25 ft tới các lỗ khác nhau"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Bài nào không đạt 5/5 thì làm lại. Phải hoàn thành liên tiếp mỗi lỗ một up & down, đủ 5 lỗ khác nhau, mới tính là 5/5."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện kỹ năng bump & run"],["o","Cải thiện kỹ năng flop"],["o","Cải thiện độ ổn định đưa bóng chip dừng trong 3 feet"],["o","Cải thiện kỹ năng với các gậy khác ngoài gậy chip quen dùng"],["p","Bài tập hôm nay:"],["h","1. Khối lượng lớn"],["s","50 cú bump & run tới lỗ xa"],["s","50 cú flop tới lỗ gần, từ rough cách mép green khoảng 25 ft."],["s","50 cú chip thường tới lỗ trung bình"],["s","50 cú chip dừng trong 3 feet tới nhiều lỗ khác nhau bằng pitching wedge"],["s","45/50 cú chip dừng trong 3 feet từ rough quanh green tới lỗ cách 10–15 ft"],["p","Hướng dẫn: Dùng wedge bạn hay dùng cho bump & run, hoặc đổi sang thử gậy sắt 9 hay gậy sắt 7. Với cú flop dùng wedge loft cao như thường lệ. Bài cuối dùng wedge chip quen dùng, tập trung đạt 9/10 trong mỗi bộ, 5 bộ để đạt 45/50."]]},{"a":"putt","h":"Putt","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Putt gần: cải thiện từ 3 feet"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Putt xuống dốc"],["o","Putt tính điểm (trò chơi 18 hố)"],["o","Putt từ fringe"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 3 feet"],["h","2. Putt áp lực: bài vòng tròn"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 5 feet"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 6 feet"],["s","Putt vào liên tiếp 5 bóng (một vòng quanh lỗ) từ 7 feet"],["h","3. Putt vào xuống dốc"],["s","Putt vào 8/10 bóng từ 4 feet"],["s","Putt vào 8/10 bóng từ 5 feet"],["s","Putt vào 8/10 bóng từ 6 feet"],["s","Putt vào 6/10 bóng từ 7 feet"],["s","Putt vào 6/10 bóng từ 8 feet"],["s","Putt vào 6/10 bóng từ 9 feet"],["h","4. Trò chơi 18 hố (xem hướng dẫn bên dưới)"],["s","Từ 17 putt trở xuống là qua trò chơi"],["h","5. Putt từ fringe"],["s","Lỗ gần: lag 22/25 bóng dừng trong 3 feet"],["s","Lỗ trung bình: lag 22/25 bóng dừng trong 3 feet"],["s","Lỗ xa: lag 22/25 bóng dừng trong 3 feet"]]}]},{"w":9,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR: Quỹ đạo bóng với driver"],["b","10 cú quỹ đạo cao bằng driver. Ghi số cú đúng quỹ đạo trên 10."],["b","10 cú quỹ đạo trung bình bằng driver. Ghi số cú đúng quỹ đạo trên 10."],["b","10 cú quỹ đạo thấp bằng driver. Ghi số cú đúng quỹ đạo trên 10."],["p","Hướng dẫn: 4 tuần đầu tập cú cơ bản trên sân, 4 tuần tiếp tập điều hướng bóng với draw, fade và cú thẳng. Tuần 9 bắt đầu tập quỹ đạo để đánh tốt cú cao, trung bình và thấp, những cú quan trọng cho các tình huống và điều kiện sân khác nhau. Dùng driver đánh 10 cú cho mỗi quỹ đạo và ghi số cú thành công trên 10 vào phiếu. Xác định trước thế nào là thấp, trung bình, cao. Quỹ đạo trung bình thường khó nhất, vì đa số đã quen đánh drive cao bay xa và cũng biết đánh punch thấp. Ngày 2 và ngày 3 cố vượt tổng số cú thành công của mỗi kiểu."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR: Quỹ đạo bóng với gậy sắt 7"],["b","Đánh 10 cú quỹ đạo cao bằng gậy sắt 7. Ghi số cú thành công trên 10."],["b","Đánh 10 cú quỹ đạo trung bình bằng gậy sắt 7. Ghi số cú thành công trên 10."],["b","Đánh 10 cú quỹ đạo thấp bằng gậy sắt 7. Ghi số cú thành công trên 10."],["p","Hướng dẫn: Đưa bóng lên trước trong thế đứng để bay cao, lùi bóng ra sau để bay thấp. Đánh 10 cú mỗi quỹ đạo và ghi số cú thành công vào phiếu. Ngày 2 và ngày 3 cố tăng tổng số cú thành công."]]},{"a":"scr","h":"Up & down và chip kết hợp","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Xây dựng sự tự tin khi cứu par"],["o","Xây dựng khả năng up & down từ nhiều vị trí khác nhau"],["o","Xây dựng kỹ năng chip tới lỗ ở nhiều khoảng cách"],["o","Xây dựng khả năng putt từ những khoảng cách còn lại sau cú chip"],["p","Bài tập tăng tỉ lệ up & down:"],["h","1. Mô phỏng trên sân khối lượng lớn"],["s","Hoàn thành 100 up & down tới lỗ gần"],["s","Hoàn thành 100 up & down tới lỗ trung bình"],["s","Hoàn thành 100 up & down tới lỗ xa"],["p","Hướng dẫn: Thay đổi thế bóng, khoảng cách tới mép green… để mỗi lượt là một tình huống up & down khác. Dùng bộ 5 bóng cho nhanh. Chip 5 bóng tới lỗ gần rồi cố putt vào cả 5. Đạt 100 up & down thì chuyển sang lỗ trung bình và lỗ xa, làm tương tự. Càng tập trung càng xong sớm bài nặng này. Hy vọng bạn chỉ cần khoảng 150 cú chip hoặc ít hơn để đạt 100 lượt thành công. Chip sát lỗ để putt dễ hơn."]]},{"a":"putt","h":"Putt","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Putt gần: cải thiện từ 4 feet"],["o","Putt đường bẻ: cải thiện độ ổn định khi putt vào"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 4 feet"],["h","2. Putt xa (lag)"],["s","50/50 bóng dừng trong 3 feet quanh lỗ từ 30 feet. Không đạt thì làm lại."],["s","48/50 bóng dừng trong 3 feet quanh lỗ từ 40 feet. Không đạt thì làm lại."],["s","46/50 bóng dừng trong 3 feet quanh lỗ từ 50 feet. Không đạt thì làm lại."],["h","3. Putt đường bẻ: cải thiện trong 10 feet"],["s","Putt vào 9/10 bóng bẻ trái từ 5 feet"],["s","Putt vào 9/10 bóng bẻ phải từ 5 feet"],["s","Putt vào 9/10 bóng bẻ trái từ 7 feet"],["s","Putt vào 9/10 bóng bẻ phải từ 7 feet"],["s","Putt vào 10/10 bóng từ 4 feet. Tự chọn đường bẻ."],["h","4. Putt xuống dốc"],["s","Putt vào 6/10 bóng bẻ trái từ 6 feet"],["s","Putt vào 6/10 bóng bẻ phải từ 6 feet"],["s","Putt vào 5/10 bóng bẻ trái từ 8 feet"],["s","Putt vào 5/10 bóng bẻ phải từ 8 feet"],["h","5. Putt từ fringe"],["s","Lỗ gần: lag 10/10 bóng dừng trong 3 feet"],["s","Lỗ trung bình: lag 10/10 bóng dừng trong 3 feet"],["s","Lỗ xa: lag 10/10 bóng dừng trong 3 feet"],["h","6. Putt áp lực: vào liên tiếp"],["s","Putt vào liên tiếp 10 bóng, đường phẳng (không bẻ), từ 5 foot"]]}]},{"w":10,"d":0,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ FIR: Quỹ đạo bóng với driver"],["b","Đánh 5 cú quỹ đạo cao bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú quỹ đạo trung bình bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú quỹ đạo thấp bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú quỹ đạo cao bằng gỗ fairway. Ghi số lần vào fairway."],["b","Đánh 5 cú quỹ đạo trung bình bằng gỗ fairway. Ghi số lần vào fairway."],["b","Đánh 5 cú quỹ đạo thấp bằng gỗ fairway. Ghi số lần vào fairway."],["p","Hướng dẫn: Xác định trước thế nào là quỹ đạo thấp, trung bình, cao. Đánh 5 cú mỗi quỹ đạo với driver và gỗ fairway, tổng 30 cú. Ghi số cú thành công của mỗi kiểu để so giữa các buổi và biết điểm mạnh, điểm yếu. Ngày 2 và ngày 3 cố vượt số cú thành công của mỗi kiểu."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR: Quỹ đạo bóng với gậy sắt"],["b","Đánh 5 cú quỹ đạo cao bằng gậy sắt 4. Ghi số lần vào green trên 5."],["b","Đánh 5 cú quỹ đạo trung bình bằng gậy sắt 4. Ghi số lần vào green trên 5."],["b","Đánh 5 cú quỹ đạo thấp bằng gậy sắt 4. Ghi số lần vào green trên 5."],["b","Đánh 5 cú quỹ đạo cao bằng gậy sắt 5. Ghi số lần vào green trên 5."],["b","Đánh 5 cú quỹ đạo trung bình bằng gậy sắt 5. Ghi số lần vào green trên 5."],["b","Đánh 5 cú quỹ đạo thấp bằng gậy sắt 5. Ghi số lần vào green trên 5."],["p","Hướng dẫn: Đưa bóng lên trước trong thế đứng để bay cao, lùi bóng ra sau để bay thấp. Đánh 5 cú mỗi quỹ đạo, ghi vào phiếu số cú đúng quỹ đạo và sẽ vào green đúng chuẩn. Cố tăng tổng số cú thành công ở mỗi buổi tập sau (ngày 2 và ngày 3)."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["d","1. Hoàn thành 10 up & down bằng cú flop tới lỗ xa"],["d","2. Hoàn thành 10 up & down bằng bump & run tới lỗ xa"],["d","3. Hoàn thành 10 up & down bằng cú chip quỹ đạo trung bình tới lỗ xa"],["p","Hướng dẫn: Tìm một lỗ xa, cách vị trí của bạn trong rough quanh green từ 40 ft trở lên. Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ nhiều thế bóng"],["o","Cải thiện khả năng chịu áp lực khi chip"],["p","Bài tập hôm nay:"],["h","1. Mô phỏng chip áp lực tới lỗ cách 20–30 ft"],["s","40/50 cú chip dừng trong 3 feet khi bóng lún trong cỏ"],["s","40/50 cú chip dừng trong 3 feet khi bóng nằm nổi trên rough"],["s","40/50 cú chip dừng trong 3 feet từ fringe"],["p","Hướng dẫn: Chọn lỗ ở giữa green tập hoặc cách khoảng 20–30 ft. Đạt 40/50 cú chip dừng trong 3 feet cho cả 3 thế bóng."]]},{"a":"putt","h":"Putt","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Putt gần: cải thiện ở 2 feet và 3 feet"],["o","Putt áp lực: cải thiện độ ổn định khi putt vào"],["o","Putt xa: cải thiện khả năng đưa bóng dừng trong 3 feet từ xa"],["p","Bài tập cải thiện chỉ số putt:"],["h","1. Khởi động"],["s","Putt vào 100 bóng từ 4 feet"],["h","2. Chuỗi putt xa: thi đấu"],["s","Lag liên tiếp 50/50 bóng dừng trong 3 feet quanh lỗ từ 25 feet"],["s","Sau đó tiếp tục, xem có kéo chuỗi lên 100 bóng liên tiếp được không vì đã có 50. Ngày 2 và ngày 3 cố phá kỷ lục."],["h","3. Cải thiện putt đường bẻ"],["s","Putt vào 50 bóng bẻ trái từ 10 feet"],["s","Putt vào 50 bóng đường phẳng (không bẻ) từ 10 feet"],["s","Putt vào 50 bóng bẻ phải từ 10 feet"],["h","4. 100 bóng vào lỗ"],["s","Putt vào 100 bóng từ 5 feet ở các vị trí tự chọn quanh lỗ."]]}]},{"w":11,"d":1,"s":[{"a":"fir","h":"Fairway (FIR)","m":25,"it":[["p","Buổi này chỉ dành cho ngày 1. Ngày 2 và ngày 3 là các buổi riêng."],["p","Bài tập tăng tỉ lệ FIR: Quỹ đạo bóng với driver"],["b","Đánh 5 cú draw cao bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú draw trung bình bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú draw thấp bằng driver. Ghi số lần vào fairway."],["b","Đánh 5 cú draw cao bằng gỗ fairway. Ghi số lần vào fairway."],["b","Đánh 5 cú draw trung bình bằng gỗ fairway. Ghi số lần vào fairway."],["b","Đánh 5 cú draw thấp bằng gỗ fairway. Ghi số lần vào fairway."],["p","Hướng dẫn: Giờ kết hợp điều hướng bóng với quỹ đạo để tạo một tuần tập thử thách. Bạn sắp xong khoá 12 tuần nên đoạn cuối phải khó, nhất là nếu các bài trước bạn thấy nhẹ nhàng. Đánh 5 cú cho mỗi bài trên và ghi số lần vào fairway. Sai quỹ đạo hoặc bóng không cong đúng kiểu thì không tính, kể cả khi rơi vào vùng fairway."]]},{"a":"gir","h":"Green (GIR)","m":25,"it":[["p","Bài tập tăng tỉ lệ GIR: Quỹ đạo bóng với gậy sắt"],["b","Đánh 5 cú draw cao bằng gậy sắt 5. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw trung bình bằng gậy sắt 5. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw thấp bằng gậy sắt 5. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw cao bằng gậy sắt 6. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw trung bình bằng gậy sắt 6. Ghi số lần vào green trên 5."],["b","Đánh 5 cú draw thấp bằng gậy sắt 6. Ghi số lần vào green trên 5."],["p","Hướng dẫn: Đánh 5 cú cho mỗi bài trên và ghi số lần vào green. Sai quỹ đạo hoặc bóng không cong đúng kiểu thì không tính, kể cả khi rơi vào vùng green."]]},{"a":"scr","h":"Up & down (cứu par)","m":45,"it":[["p","Bài tập tăng tỉ lệ up & down:"],["d","1. 15/18 up & down từ cách mép green 30 ft tới lỗ xa ở phía bên kia green."],["d","2. 18/18 up & down từ cách mép green 10 ft tới lỗ trung bình"],["p","Hướng dẫn: Chỉ dùng một bóng để tập trung tối đa. Chip bóng về phía lỗ rồi putt một lần vào lỗ để hoàn thành up & down. Ở bài 1 và 2, nếu chip chưa sát thì cú putt phải cứu bạn. Không đạt chỉ tiêu thì làm lại."]]},{"a":"chip","h":"Chip","m":45,"it":[["p","Mục tiêu hôm nay:"],["o","Cải thiện chip từ fringe"],["o","Cải thiện kiểm soát khoảng cách"],["p","Bài tập hôm nay:"],["d","1