  k text; s jsonb; b jsonb; v_prog uuid; v_sess uuid; i int;
begin
  for k in select jsonb_object_keys(d) loop
    select id into v_prog from public.training_programs where code = k;
    for s in select * from jsonb_array_elements(d -> k) loop
      insert into public.training_program_sessions (program_id, week_no, day_no)
      values (v_prog, (s ->> 'w')::int, (s ->> 'd')::int) returning id into v_sess;
      i := 0;
      for b in select * from jsonb_array_elements(s -> 's') loop
        insert into public.training_program_blocks (session_id, sort_order, area, title_vi, est_minutes, lines)
        values (v_sess, i, b ->> 'a', b ->> 'h', round((b ->> 'm')::numeric)::int,
                (select coalesce(jsonb_agg(jsonb_build_object('t', x ->> 0, 'vi', x ->> 1, 'en', '') order by n), '[]')
                 from jsonb_array_elements(b -> 'it') with ordinality as y(x, n)));
        i := i + 1;
      end loop;
    end loop;
  end loop;
end $$;
